CREATE OR REPLACE FUNCTION public.adjust_personnel_salary(p_personnel_id uuid, p_type text, p_delta numeric, p_reason text, p_effective_date date DEFAULT CURRENT_DATE, p_actor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_personnel record;
    v_amount_before numeric;
    v_amount_after numeric;
    v_signed_delta numeric;
    v_actor_id uuid := public.current_user_profile_id();
    v_actor_name text;
    v_tenant_id uuid;
    v_adjustment public.salary_adjustments;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    -- ── Caller verification (0055 pattern) ─────────────────────────────
    if not v_caller_is_service_role then
        if auth.uid() is null then
            raise exception 'adjust_personnel_salary: an authenticated caller is required';
        end if;
        if not public.has_any_role(array['super_admin', 'financial_officer']) then
            raise exception 'adjust_personnel_salary: only super_admin / financial_officer may adjust salaries';
        end if;
    end if;

    -- ── Input validation (mirrors the desktop UI's mandatory-reason rule) ─
    if p_type not in ('raise', 'cut', 'bonus', 'deduction') then
        raise exception 'adjust_personnel_salary: invalid adjustment type %', p_type;
    end if;
    if p_delta is null or p_delta <= 0 then
        raise exception 'adjust_personnel_salary: the adjustment amount must be positive';
    end if;
    if p_reason is null or length(trim(p_reason)) < 5 then
        raise exception 'adjust_personnel_salary: a formal justification of at least 5 characters is mandatory';
    end if;

    -- ── Lock the personnel row (atomic read-modify-write) ───────────────
    select * into v_personnel
      from public.personnel
     where id = p_personnel_id
     for update;

    if not found then
        raise exception 'adjust_personnel_salary: personnel record % not found', p_personnel_id;
    end if;

    v_tenant_id := v_personnel.tenant_id;

    -- Tenant guard (SEC-112 lesson): the caller's working tenant must own
    -- the personnel row. Global admins (tenant-less profiles) and the
    -- service_role are the 0055-trusted exemptions.
    if not v_caller_is_service_role
       and public.current_tenant_id() is not null
       and public.current_tenant_id() <> v_tenant_id then
        raise exception 'adjust_personnel_salary: cross-tenant adjustment refused (personnel tenant % does not match the caller''s working tenant)', v_tenant_id;
    end if;

    v_amount_before := coalesce(v_personnel.base_salary, 0);

    -- Actor display name: the UI-passed name wins, else the profile's
    -- display_name, else a neutral fallback.
    select coalesce(display_name, '') into v_actor_name
      from public.user_profiles
     where id = v_actor_id
       and v_actor_id is not null;
    v_actor_name := coalesce(nullif(trim(coalesce(p_actor_name, '')), ''), nullif(v_actor_name, ''), 'Admin');

    -- ── The four adjustment semantics (the blueprint's table) ───────────
    -- INVARIANT: delta = amount_after - amount_before on every row (the
    -- table CHECK enforces it for raise/cut). For a FLOORED cut the delta
    -- records the reduction that ACTUALLY happened, not the requested
    -- magnitude — a deviation from the blueprint's "-abs(p_delta)" recorded
    -- here because the blueprint's version violates its own row invariant
    -- (amount_after = amount_before + delta) whenever the floor engages.
    if p_type = 'raise' then
        v_amount_after := v_amount_before + abs(p_delta);
        v_signed_delta := abs(p_delta);
    elsif p_type = 'cut' then
        v_amount_after := greatest(0, v_amount_before - abs(p_delta));
        v_signed_delta := v_amount_after - v_amount_before;
    elsif p_type = 'bonus' then
        v_amount_after := v_amount_before;            -- one-off: base unchanged
        v_signed_delta := abs(p_delta);
    else -- 'deduction'
        v_amount_after := v_amount_before;            -- one-off: base unchanged
        v_signed_delta := -abs(p_delta);
    end if;

    -- ── Update the base salary (raise/cut only) ─────────────────────────
    if p_type in ('raise', 'cut') then
        update public.personnel
           set base_salary = v_amount_after,
               updated_at = now()
         where id = p_personnel_id;
    end if;

    -- ── The immutable adjustment row ─────────────────────────────────────
    insert into public.salary_adjustments (
        tenant_id, personnel_id, type, amount_before, amount_after,
        delta, reason, effective_date, approved_by, approved_by_name
    ) values (
        v_tenant_id, p_personnel_id, p_type, v_amount_before, v_amount_after,
        v_signed_delta, trim(p_reason), coalesce(p_effective_date, current_date), v_actor_id, v_actor_name
    )
    returning * into v_adjustment;

    -- ── Master audit log (0014) ──────────────────────────────────────────
    perform public.write_audit_log(
        p_tenant_id   := v_tenant_id,
        p_action      := 'personnel.salary_adjusted',
        p_entity_type := 'personnel',
        p_entity_id   := p_personnel_id,
        p_actor_id    := v_actor_id,
        p_actor_name  := v_actor_name,
        p_before_json := jsonb_build_object('salary', v_amount_before),
        p_after_json  := jsonb_build_object('salary', v_amount_after, 'type', p_type, 'delta', v_signed_delta, 'reason', trim(p_reason)),
        p_note        := format('Salary adjusted (%s: %s DZD)', p_type, v_signed_delta)
    );

    return jsonb_build_object(
        'adjustment', to_jsonb(v_adjustment),
        'base_salary_after', v_amount_after
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_expense(p_tenant_id uuid, p_ticket_id uuid, p_approver_profile_id uuid, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_ticket record;
    v_audit_id uuid;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    -- ── Caller verification + actor binding (SEC-118, the 0055 pattern) ──
    if not v_caller_is_service_role then
        if auth.uid() is null then
            raise exception 'approve_expense: an authenticated caller is required';
        end if;
        if not public.has_any_role(array['super_admin', 'financial_officer', 'manager']) then
            raise exception 'approve_expense: only super_admin / financial_officer / manager may approve expenses';
        end if;
        if p_approver_profile_id is distinct from public.current_user_profile_id() then
            raise exception 'approve_expense: p_approver_profile_id must be the caller''s own profile (SEC-118 actor binding) — approvals cannot be recorded in another profile''s name';
        end if;
    end if;

    select * into v_ticket from public.expense_tickets where id = p_ticket_id and tenant_id = p_tenant_id;
    if not found then raise exception 'Expense ticket not found'; end if;

    if v_ticket.submitted_by = p_approver_profile_id then
        raise exception 'Self-approval is forbidden (plan §08)';
    end if;

    if v_ticket.status <> 'pending_approval' then
        raise exception 'Ticket is not pending approval (current: %)', v_ticket.status;
    end if;

    update public.expense_tickets
       set status = 'approved_funds_released',
           approved_by = p_approver_profile_id,
           approved_at = now(),
           approval_note = p_note,
           disbursed_at = now(),
           updated_at = now()
     where id = p_ticket_id;

    v_audit_id := public.write_audit_log(
        p_tenant_id := p_tenant_id,
        p_action := 'expense.approve',
        p_entity_type := 'expense_ticket',
        p_entity_id := p_ticket_id,
        p_actor_id := p_approver_profile_id,
        p_after_json := jsonb_build_object('status', 'approved_funds_released', 'note', p_note)
    );

    return v_audit_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.audit_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_entity   text;
    v_action   text;
    v_entity_id uuid;
    v_tenant   uuid;
    v_actor_id  uuid;
    v_actor_name text;
    v_actor_role text;
    v_before   jsonb;
    v_after    jsonb;
    v_row      jsonb;
begin
    -- Snapshots (updated_at stripped — the touch trigger always rewrites it).
    if TG_OP = 'UPDATE' then
        v_before := to_jsonb(OLD) - 'updated_at';
        v_after  := to_jsonb(NEW) - 'updated_at';
        -- No-op guard: only the touch timestamp changed → not a mutation.
        if v_before is not distinct from v_after then
            return null;
        end if;
    elsif TG_OP = 'INSERT' then
        v_before := null;
        v_after  := to_jsonb(NEW) - 'updated_at';
    else -- DELETE
        v_before := to_jsonb(OLD) - 'updated_at';
        v_after  := null;
    end if;

    v_row := case TG_OP when 'DELETE' then to_jsonb(OLD) else to_jsonb(NEW) end;

    -- Entity + action mapping (AuditActions wire-code style: entity.action).
    v_entity := (case TG_TABLE_NAME
        when 'parents'                   then 'parent'
        when 'students'                  then 'student'
        when 'pricing_configs'           then 'pricing_config'
        when 'grade_level_tuition'       then 'pricing_grade'
        when 'transport_destinations'    then 'pricing_transport'
        when 'complementary_services'    then 'pricing_complementary_service'
        when 'additional_services'       then 'pricing_additional_service'
        when 'discounts'                 then 'pricing_discount'
        else TG_TABLE_NAME
    end);
    v_action := v_entity || '.' ||
        (case TG_OP when 'INSERT' then 'create' when 'UPDATE' then 'update' else 'delete' end);

    v_entity_id := (v_row ->> 'id')::uuid;

    -- Tenant resolution: CRM rows carry tenant_id; pricing children resolve
    -- through their pricing_config.
    if TG_TABLE_NAME in ('parents', 'students', 'pricing_configs') then
        v_tenant := (v_row ->> 'tenant_id')::uuid;
    else
        v_tenant := (select pc.tenant_id
                       from public.pricing_configs pc
                      where pc.id = (v_row ->> 'pricing_config_id')::uuid);
    end if;
    if v_tenant is null then
        v_tenant := public.current_tenant_id();
    end if;
    -- Defensive: an unresolvable tenant must NEVER roll back the business
    -- write — skip the audit row and warn (observable in Postgres logs).
    if v_tenant is null then
        raise warning 'audit_row_change: tenant unresolvable for % %', TG_OP, TG_TABLE_NAME;
        return null;
    end if;

    -- Actor attribution (auth context; NULL under service-role jobs).
    select id into v_actor_id
      from public.user_profiles
     where auth_user_id = auth.uid()
     limit 1;
    if v_actor_id is not null then
        select coalesce(display_name, email) into v_actor_name
          from public.user_profiles
         where id = v_actor_id;
        select r.code into v_actor_role
          from public.role_assignments ra
          join public.roles r on r.id = ra.role_id
         where ra.user_profile_id = v_actor_id
           and ra.revoked_at is null
         order by r.code
         limit 1;
    else
        v_actor_name := 'System';
        v_actor_role := null;
    end if;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := v_action,
        p_entity_type := v_entity,
        p_entity_id   := v_entity_id,
        p_actor_id    := v_actor_id,
        p_actor_name  := v_actor_name,
        p_actor_role  := v_actor_role,
        p_before_json := v_before,
        p_after_json  := v_after,
        p_note        := 'Capture automatique (déclencheur ' || TG_OP || ' sur ' || TG_TABLE_NAME || ')'
    );

    return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.batch_register_family(p_tenant_id uuid, p_parent jsonb, p_students jsonb, p_actor_profile_id uuid, p_activation_code text DEFAULT NULL::text)
 RETURNS TABLE(parent_id uuid, student_ids uuid[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_parent_id uuid;
    v_student_ids uuid[] := '{}';
    v_student_id uuid;
    v_student jsonb;
    v_parent_code text;
    v_student_code text;
    v_seq integer;
    v_activation_code text;
    v_audit_id uuid;
begin
    -- DRIFT-001 / T-115 (migration 0065): the parent code is CANONICAL and
    -- DETERMINISTIC — FNV-1a of the identity fields, exactly like the
    -- desktop's SupabaseParentRepository and the approve-signup-request EF.
    -- The unique (tenant_id, parent_code) constraint then refuses duplicate
    -- family registrations for the same identity — that refusal IS the
    -- canonical idempotency contract ("the dedup match IS the code").
    if coalesce(btrim(p_parent->>'primary_phone'), '') = ''
       and coalesce(btrim(p_parent->>'display_name'), '') = ''
       and coalesce(btrim(p_parent->>'first_name'), '') = ''
       and coalesce(btrim(p_parent->>'last_name'), '') = '' then
        raise exception 'batch_register_family: parent identity fields required (primary_phone / display_name / first_name / last_name) — the canonical code generator has no random fallback (DRIFT-001, migration 0065)';
    end if;

    v_parent_code := public.fn_deterministic_parent_code(
        extract(year from now())::int,
        p_parent->>'primary_phone',
        p_parent->>'display_name',
        p_parent->>'first_name',
        p_parent->>'last_name'
    );

    -- Insert parent
    insert into public.parents (
        tenant_id, parent_code, first_name, last_name, primary_phone,
        secondary_phone, email, national_id, occupation, address, city,
        postal_code, relationship, notes, is_active, created_at, updated_at
    ) values (
        p_tenant_id, v_parent_code,
        p_parent->>'first_name', p_parent->>'last_name', p_parent->>'primary_phone',
        p_parent->>'secondary_phone', p_parent->>'email', p_parent->>'national_id',
        p_parent->>'occupation', p_parent->>'address', p_parent->>'city',
        p_parent->>'postal_code', p_parent->>'relationship', p_parent->>'notes',
        true, now(), now()
    )
    returning id into v_parent_id;

    -- Insert students (sequential ELV-{year}-{6-digit} — canonical student
    -- format per core/format/id.ts; DRIFT-001's RPC finding targets the
    -- PARENT code, the deterministic-ELV variant belongs to the
    -- sync/import upsert paths).
    for v_student in select * from jsonb_array_elements(p_students)
    loop
        v_seq := nextval('public.student_seq');
        v_student_code := 'ELV-' || extract(year from now())::text || '-' || lpad(v_seq::text, 6, '0');

        insert into public.students (
            tenant_id, parent_id, student_code, first_name, middle_name, last_name,
            date_of_birth, gender, grade_level_id, class_id, enrollment_date,
            enrollment_status, medical_notes, is_active, created_at, updated_at
        ) values (
            p_tenant_id, v_parent_id, v_student_code,
            v_student->>'first_name', v_student->>'middle_name', v_student->>'last_name',
            (v_student->>'date_of_birth')::date,
            v_student->>'gender',
            nullif(v_student->>'grade_level_id', '')::uuid,
            nullif(v_student->>'class_id', '')::uuid,
            current_date, 'enrolled', v_student->>'medical_notes',
            true, now(), now()
        )
        returning id into v_student_id;
        v_student_ids := array_append(v_student_ids, v_student_id);
    end loop;

    -- Issue activation code (or use provided one).
    -- DRIFT-001 / T-115: the DEFAULT is now the canonical DETERMINISTIC code
    -- (same family -> same activation code on retry). Collision fallback:
    -- the 6-digit space can collide across parents in a tenant (~3.7% at
    -- 259 parents); on a collision with a DIFFERENT parent's unbound code,
    -- fall back to the random-with-uniqueness generator (safety first).
    if p_activation_code is not null then
        v_activation_code := p_activation_code;
    else
        v_activation_code := public.fn_deterministic_activation_code(v_parent_code, p_tenant_id);
        if exists (
            select 1 from public.activation_codes ac
             where ac.tenant_id = p_tenant_id
               and ac.code = v_activation_code
               and ac.bound_to_auth_user_id is null
               and ac.parent_id is distinct from v_parent_id
        ) then
            v_activation_code := public.generate_activation_code(p_tenant_id);
        end if;
    end if;

    insert into public.activation_codes (
        tenant_id, code, parent_id, issued_by, issued_at, expires_at
    ) values (
        p_tenant_id, v_activation_code, v_parent_id, p_actor_profile_id, now(), now() + interval '30 days'
    );

    -- Write audit log
    v_audit_id := public.write_audit_log(
        p_tenant_id := p_tenant_id,
        p_action := 'parent.batch_register',
        p_entity_type := 'parent',
        p_entity_id := v_parent_id,
        p_actor_id := p_actor_profile_id,
        p_before_json := null,
        p_after_json := jsonb_build_object('parent_id', v_parent_id, 'student_ids', v_student_ids, 'activation_code', v_activation_code, 'parent_code', v_parent_code, 'code_rule', 'deterministic_fnv1a_0065'),
        p_note := 'Atomic batch registration: parent + ' || cardinality(v_student_ids) || ' students (canonical deterministic parent code, migration 0065)'
    );

    return query select v_parent_id, v_student_ids;
end;
$function$

CREATE OR REPLACE FUNCTION public.bind_activation_code(p_tenant_id uuid, p_code text, p_auth_user_id uuid)
 RETURNS TABLE(parent_id uuid, parent_full_name text, student_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_activation record;
    v_parent_id uuid;
    v_existing_auth_user_id uuid;
    v_caller_is_service_role boolean;
begin
    -- ── SEC-110: caller verification ─────────────────────────────────
    -- Direct PostgREST callers (user JWT) must bind THEMSELVES only.
    -- The bind-activation-code Edge Function calls via service_role
    -- after verifying the caller's JWT (ctx.userId = the verified
    -- auth.users.id) — service_role is trusted server-side code.
    -- Anonymous / forged-token callers: auth.uid() IS NULL → rejected.
    v_caller_is_service_role := coalesce(auth.jwt() ->> 'role', '') = 'service_role';

    if p_auth_user_id is null then
        raise exception 'bind_activation_code: p_auth_user_id is required (SEC-110)';
    end if;

    if not v_caller_is_service_role
       and (auth.uid() is null or p_auth_user_id <> auth.uid()) then
        raise exception 'bind_activation_code: p_auth_user_id must match the authenticated caller (SEC-110)';
    end if;

    -- Lock the activation code row
    select * into v_activation
      from public.activation_codes
     where tenant_id = p_tenant_id
       and code = p_code
       and bound_to_auth_user_id is null
     for update;

    if not found then
        raise exception 'Invalid or already-used activation code';
    end if;

    if v_activation.expires_at < now() then
        raise exception 'Activation code has expired';
    end if;

    v_parent_id := v_activation.parent_id;

    -- ── STUDENT-101: silent re-bind guard ────────────────────────────
    -- Refuse to transfer a parent record that is already bound to a
    -- DIFFERENT auth user. Re-binding the SAME user (retry after a
    -- partial failure) stays allowed.
    select auth_user_id into v_existing_auth_user_id
      from public.parents
     where id = v_parent_id
     for update;

    if v_existing_auth_user_id is not null
       and v_existing_auth_user_id <> p_auth_user_id then
        raise exception 'bind_activation_code: parent % is already bound to another account — contact the school office', v_parent_id;
    end if;

    -- Mark the code as bound
    update public.activation_codes
       set bound_to_auth_user_id = p_auth_user_id,
           bound_at = now()
     where id = v_activation.id;

    -- Bind the auth.users.id to the parent record
    update public.parents
       set auth_user_id = p_auth_user_id
     where id = v_parent_id;

    -- ── PARENT-103: audit the direct-RPC path ────────────────────────
    -- The EF path already writes its own richer audit entry
    -- (activation_code.bind, with request id) AFTER this RPC returns;
    -- auditing from here too would duplicate it. Direct PostgREST
    -- callers bypass the EF entirely, so THIS path is audited here.
    if not v_caller_is_service_role then
        insert into public.audit_logs (
            id, tenant_id, action, entity_type, entity_id,
            actor_id, actor_name, after_json, note, occurred_at
        ) values (
            public.gen_uuid(), p_tenant_id, 'activation_code.bind_rpc', 'parent', v_parent_id,
            null, 'direct-rpc-caller',
            jsonb_build_object('activation_code', p_code, 'auth_user_id', p_auth_user_id),
            'bind_activation_code called directly via PostgREST (not via the Edge Function)',
            now()
        );
    end if;

    -- Return parent + student count for the response
    return query
        select p.id as parent_id,
               (p.first_name || ' ' || p.last_name) as parent_full_name,
               count(s.id)::bigint as student_count
          from public.parents p
          left join public.students s on s.parent_id = p.id and s.deleted_at is null
         where p.id = v_parent_id
         group by p.id, p.first_name, p.last_name;
end;
$function$

CREATE OR REPLACE FUNCTION public.chat_channels_derive_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
    if exists (
        select 1
          from unnest(new.member_ids) as m
         where not public.profile_has_staff_role_in_tenant(m, new.tenant_id)
    ) then
        new.scope := 'portal';
    else
        new.scope := 'internal';
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.collect_and_allocate_payment(p_tenant_id uuid, p_parent_id uuid, p_student_id uuid, p_amount numeric, p_method text, p_category text, p_installment_id uuid, p_proof_path text, p_notes text, p_actor_id uuid, p_actor_name text, p_check_number text DEFAULT NULL::text, p_check_bank_name text DEFAULT NULL::text, p_check_issue_date date DEFAULT NULL::date, p_check_clearance_date date DEFAULT NULL::date, p_transfer_reference text DEFAULT NULL::text, p_transfer_source_bank text DEFAULT NULL::text, p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(payment_id uuid, receipt_number text, payment_status text, total_allocated numeric, unallocated_credit numeric, allocations jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_year INT := EXTRACT(YEAR FROM NOW()); v_seq INT; v_receipt TEXT; v_status TEXT;
  v_payment_id UUID := gen_random_uuid(); v_ledger_id TEXT; v_remaining NUMERIC;
  v_alloc JSONB := '[]'::JSONB; v_alloc_item JSONB; v_ins RECORD; v_unallocated NUMERIC := 0;
  v_account_id TEXT; v_ins_remaining NUMERIC; v_allocate NUMERIC; v_new_paid NUMERIC;
  v_new_pending NUMERIC; v_new_status TEXT; v_fully BOOLEAN;
  -- T-310: the RESOLVED actor (name + role).
  v_actor_name TEXT; v_actor_role TEXT;
  -- T-436: the payment-made year (INV-18) + the allocation target year.
  v_payment_year_id UUID;
BEGIN
  IF p_amount <= 0 THEN RAISE EXCEPTION 'Payment amount must be > 0 (got %)', p_amount; END IF;

  -- T-436 (ADR-030): the payment's academic year — the tenant window
  -- containing the collection date (NULL when outside: the read-side
  -- INV-14 fallback resolves it).
  v_payment_year_id := public.resolve_academic_year_id_for_date(
      (p_as_of AT TIME ZONE 'UTC')::date, p_tenant_id);

  -- T-310 (AUDIT-502): resolve the actor ONCE, up-front.
  IF p_actor_name IS NOT NULL AND p_actor_name <> '' AND p_actor_name <> p_actor_id::TEXT THEN
    v_actor_name := p_actor_name;
  ELSE
    SELECT coalesce(up.display_name, up.email) INTO v_actor_name
      FROM public.user_profiles up
     WHERE up.id = p_actor_id OR up.auth_user_id = p_actor_id
     ORDER BY (up.id = p_actor_id) DESC
     LIMIT 1;
    v_actor_name := coalesce(v_actor_name, 'System');
  END IF;
  SELECT r.code INTO v_actor_role
    FROM public.role_assignments ra
    JOIN public.roles r ON r.id = ra.role_id
   WHERE ra.user_profile_id = (
         SELECT up.id FROM public.user_profiles up
          WHERE up.id = p_actor_id OR up.auth_user_id = p_actor_id
          ORDER BY (up.id = p_actor_id) DESC LIMIT 1)
     AND ra.revoked_at IS NULL
   ORDER BY r.code
   LIMIT 1;

  v_status := CASE WHEN p_method = 'cash' THEN 'paid' ELSE 'pending' END;

  SELECT COALESCE(MAX(CAST(SUBSTRING(pay.receipt_number FROM '\d{6}$') AS INT)), 0) + 1 INTO v_seq
  FROM payments pay
  WHERE pay.tenant_id = p_tenant_id AND pay.receipt_number LIKE 'REC-' || v_year || '-%';
  v_receipt := 'REC-' || v_year || '-' || LPAD(v_seq::TEXT, 6, '0');

  -- ADR-023: p_category NULL = multi-service — stored as NULL (the payments
  -- row renders "Multi-services"; per-service truth lives in
  -- payment_allocations). Concrete categories are stored verbatim (T-060).
  INSERT INTO payments (
    id, tenant_id, payment_number, receipt_number, parent_id, student_id, amount,
    method, status, category, installment_id, proof_path, notes,
    check_number, check_bank_name, check_issue_date, check_clearance_date,
    transfer_reference, transfer_source_bank,
    collected_by, collected_at, created_at, updated_at,
    academic_year_id
  ) VALUES (
    v_payment_id, p_tenant_id, v_receipt, v_receipt, p_parent_id, p_student_id, p_amount,
    p_method, v_status, p_category, p_installment_id, p_proof_path, p_notes,
    p_check_number, p_check_bank_name, p_check_issue_date, p_check_clearance_date,
    p_transfer_reference, p_transfer_source_bank,
    p_actor_id, p_as_of, p_as_of, p_as_of,
    v_payment_year_id
  );

  -- ADR-023: the cross-category payment entry books ONE entry (the revert
  -- RPC reverses a single entry by source_id) on the synthetic account
  -- `parent:{id}:category:all` with a NULL category. Parent-level replay
  -- (Σ signed balances) reduces the outstanding correctly; per-category
  -- views read payment_allocations.
  v_account_id := 'parent:' || p_parent_id || ':category:' || COALESCE(p_category, 'all');
  IF p_student_id IS NOT NULL THEN v_account_id := v_account_id || ':student:' || p_student_id; END IF;
  v_ledger_id := 'led-' || EXTRACT(EPOCH FROM NOW()) || '-' || SUBSTRING(gen_random_uuid()::TEXT, 1, 8);
  INSERT INTO ledger_entries (
    entry_number, tenant_id, account_id, parent_id, student_id, category, amount,
    entry_type, source_type, source_id, method, receipt_number, payment_status,
    reverses_id, description, actor_id, actor_name, at, metadata
  ) VALUES (
    v_ledger_id, p_tenant_id, v_account_id, p_parent_id, p_student_id,
    p_category, -p_amount, 'payment', 'payment', v_payment_id::TEXT,
    p_method, v_receipt, v_status, NULL,
    'Encaissement ' || v_receipt || ' — ' || p_method || ' (' || COALESCE(p_category, 'multi-services') || ')',
    p_actor_id::TEXT, v_actor_name, p_as_of,
    JSONB_BUILD_OBJECT(
      'installmentId', p_installment_id, 'proofUrl', p_proof_path,
      'checkNumber', p_check_number, 'checkBankName', p_check_bank_name,
      'checkIssueDate', p_check_issue_date, 'checkClearanceDate', p_check_clearance_date,
      'transferReference', p_transfer_reference, 'transferSourceBank', p_transfer_source_bank
    )
  );

  v_remaining := p_amount;
  IF v_status = 'paid' THEN
    FOR v_ins IN
      SELECT id, amount_due, amount_paid, amount_pending, due_date, status, category, label,
             academic_year_id
      FROM installments
      WHERE parent_id = p_parent_id AND status <> 'paid'
        AND (p_category IS NULL OR category = p_category)
      ORDER BY due_date ASC, id ASC FOR UPDATE
    LOOP
      EXIT WHEN v_remaining <= 0;
      -- BUSINESS-107 (INV-4): the cleared branch now subtracts
      -- amount_pending too — a cheque pending on the tranche reduces the
      -- capacity for a subsequent CASH payment, so paid + pending can
      -- never exceed due.
      v_ins_remaining := GREATEST(0, v_ins.amount_due - v_ins.amount_paid - v_ins.amount_pending);
      IF v_ins_remaining <= 0 THEN CONTINUE; END IF;
      v_allocate := LEAST(v_remaining, v_ins_remaining);
      v_new_paid := v_ins.amount_paid + v_allocate;
      v_new_pending := v_ins.amount_pending;
      v_fully := v_new_paid >= v_ins.amount_due;
      IF v_fully THEN v_new_status := 'paid';
      ELSIF v_new_paid > 0 THEN v_new_status := 'partial';
      ELSE v_new_status := CASE WHEN v_ins.status = 'overdue' THEN 'overdue' ELSE 'pending' END; END IF;
      UPDATE installments
        SET amount_paid = v_new_paid, amount_pending = v_new_pending,
            status = v_new_status,
            paid_date = CASE WHEN v_new_status = 'paid' THEN COALESCE(paid_date, p_as_of) ELSE paid_date END
        WHERE id = v_ins.id;
      -- DATA-029: the canonical per-payment coverage record (T-330 chain).
      -- Concrete category per row — including for cross-category payments.
      -- T-436: the SETTLEMENT-TARGET year (INV-18c/18d) — the allocated
      -- installment's persisted year, resolved through the INV-14 window
      -- when the row predates the column.
      INSERT INTO payment_allocations (
        id, tenant_id, payment_id, charge_id, installment_id, category,
        allocated_amount, label, created_at, academic_year_id
      ) VALUES (
        gen_random_uuid(), p_tenant_id, v_payment_id, NULL, v_ins.id,
        v_ins.category, v_allocate, v_ins.label, p_as_of,
        COALESCE(v_ins.academic_year_id,
                 public.resolve_academic_year_id_for_date(v_ins.due_date, p_tenant_id))
      );
      v_alloc_item := JSONB_BUILD_OBJECT('installmentId', v_ins.id,
        'allocatedAmount', v_allocate, 'newAmountPaid', v_new_paid,
        'newAmountPending', v_new_pending, 'newStatus', v_new_status,
        'fullySatisfied', v_fully, 'cleared', TRUE, 'category', v_ins.category);
      v_alloc := v_alloc || JSONB_BUILD_ARRAY(v_alloc_item);
      v_remaining := v_remaining - v_allocate;
    END LOOP;
    v_unallocated := GREATEST(0, v_remaining);
    IF v_unallocated > 0 THEN
      INSERT INTO ledger_entries (
        entry_number, tenant_id, account_id, parent_id, student_id, category, amount,
        entry_type, source_type, source_id, method, receipt_number, payment_status,
        reverses_id, description, actor_id, actor_name, at, metadata
      ) VALUES (
        'led-' || EXTRACT(EPOCH FROM NOW()) || '-' || SUBSTRING(gen_random_uuid()::TEXT, 1, 8),
        p_tenant_id, 'parent:' || p_parent_id || ':category:parent_credit',
        p_parent_id, NULL, 'parent_credit', -v_unallocated,
        'adjustment', 'adjustment', 'credit-' || v_payment_id::TEXT,
        NULL, NULL, NULL, NULL,
        'Crédit parent (excédent de paiement reçu ' || v_receipt || ')',
        p_actor_id::TEXT, v_actor_name, p_as_of,
        JSONB_BUILD_OBJECT('sourcePaymentId', v_payment_id, 'unallocatedAmount', v_unallocated)
      );
    END IF;
  ELSE
    FOR v_ins IN
      SELECT id, amount_due, amount_paid, amount_pending, due_date, status, category, label,
             academic_year_id
      FROM installments
      WHERE parent_id = p_parent_id AND status <> 'paid'
        AND (p_category IS NULL OR category = p_category)
      ORDER BY due_date ASC, id ASC FOR UPDATE
    LOOP
      EXIT WHEN v_remaining <= 0;
      v_ins_remaining := GREATEST(0, v_ins.amount_due - v_ins.amount_paid - v_ins.amount_pending);
      IF v_ins_remaining <= 0 THEN CONTINUE; END IF;
      v_allocate := LEAST(v_remaining, v_ins_remaining);
      v_new_paid := v_ins.amount_paid;
      v_new_pending := v_ins.amount_pending + v_allocate;
      v_new_status := 'pending_clearance'; v_fully := FALSE;
      UPDATE installments
        SET amount_paid = v_new_paid, amount_pending = v_new_pending,
            status = v_new_status, paid_date = paid_date
        WHERE id = v_ins.id;
      -- DATA-029: pending allocations are recorded too (cleared = FALSE is
      -- derivable from the payment's status; the amount is the commitment).
      -- T-436: the settlement-target year, same as the cleared branch.
      INSERT INTO payment_allocations (
        id, tenant_id, payment_id, charge_id, installment_id, category,
        allocated_amount, label, created_at, academic_year_id
      ) VALUES (
        gen_random_uuid(), p_tenant_id, v_payment_id, NULL, v_ins.id,
        v_ins.category, v_allocate, v_ins.label, p_as_of,
        COALESCE(v_ins.academic_year_id,
                 public.resolve_academic_year_id_for_date(v_ins.due_date, p_tenant_id))
      );
      v_alloc_item := JSONB_BUILD_OBJECT('installmentId', v_ins.id,
        'allocatedAmount', v_allocate, 'newAmountPaid', v_new_paid,
        'newAmountPending', v_new_pending, 'newStatus', v_new_status,
        'fullySatisfied', FALSE, 'cleared', FALSE, 'category', v_ins.category);
      v_alloc := v_alloc || JSONB_BUILD_ARRAY(v_alloc_item);
      v_remaining := v_remaining - v_allocate;
    END LOOP;
    v_unallocated := GREATEST(0, v_remaining);
    -- No parent_credit insert for pending funds (canonical defers until clearance)
  END IF;

  -- 6. Audit log (T-310 canonical columns preserved verbatim).
  INSERT INTO audit_logs (
    id, tenant_id, action, entity_type, entity_id, actor_id, actor_name, actor_role,
    before_json, after_json, diff, note, created_at
  ) VALUES (
    gen_random_uuid(), p_tenant_id, 'payment.collect', 'payment', v_payment_id,
    p_actor_id, v_actor_name, v_actor_role,
    NULL,
    JSONB_BUILD_OBJECT(
      'amount', p_amount, 'method', p_method, 'receipt', v_receipt,
      'status', v_status, 'allocations', v_alloc,
      'unallocatedCredit', v_unallocated, 'category', p_category,
      'paymentAcademicYearId', v_payment_year_id
    ),
    JSONB_BUILD_OBJECT(
      'amount', p_amount, 'method', p_method, 'receipt', v_receipt,
      'status', v_status, 'allocations', v_alloc,
      'unallocatedCredit', v_unallocated, 'category', p_category,
      'paymentAcademicYearId', v_payment_year_id
    ),
    'Encaissement atomique via RPC collect_and_allocate_payment (canonical 0034 + structured fields; 0115 INV-4/cross-category; 0127 T-436 year stamping)',
    p_as_of
  );

  RETURN QUERY SELECT v_payment_id, v_receipt, v_status,
    p_amount - v_unallocated, v_unallocated, v_alloc;
END;
$function$

CREATE OR REPLACE FUNCTION public.compute_assessments_subject_average()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_c1  NUMERIC;
    v_c2  NUMERIC;
    v_c3  NUMERIC;
    v_cc  NUMERIC;
    v_num NUMERIC := 0;
    v_den NUMERIC := 0;
BEGIN
    -- Legacy row with no component marks at all — leave the stored value.
    IF NEW.devoir1 IS NULL AND NEW.devoir2 IS NULL
       AND NEW.examen IS NULL AND NEW.cc IS NULL THEN
        RETURN NEW;
    END IF;

    -- Weight snapshots (the values in force at entry — ADR-018 §3).
    v_c1 := COALESCE(NEW.coefficient_devoir1, 1.00);
    v_c2 := COALESCE(NEW.coefficient_devoir2, 1.00);
    v_c3 := COALESCE(NEW.coefficient_examen, 2.00);
    v_cc := COALESCE(NEW.coefficient_cc, 0.00);

    -- A positive-weight component is REQUIRED: any missing one makes the
    -- average not computable (NULL — the T-336 honesty rule).
    IF v_c1 > 0 AND NEW.devoir1 IS NULL THEN NEW.subject_average := NULL; RETURN NEW; END IF;
    IF v_c2 > 0 AND NEW.devoir2 IS NULL THEN NEW.subject_average := NULL; RETURN NEW; END IF;
    IF v_c3 > 0 AND NEW.examen IS NULL THEN NEW.subject_average := NULL; RETURN NEW; END IF;
    IF v_cc > 0 AND NEW.cc      IS NULL THEN NEW.subject_average := NULL; RETURN NEW; END IF;

    IF v_c1 > 0 THEN v_num := v_num + NEW.devoir1 * v_c1; v_den := v_den + v_c1; END IF;
    IF v_c2 > 0 THEN v_num := v_num + NEW.devoir2 * v_c2; v_den := v_den + v_c2; END IF;
    IF v_c3 > 0 THEN v_num := v_num + NEW.examen * v_c3; v_den := v_den + v_c3; END IF;
    IF v_cc > 0 THEN v_num := v_num + NEW.cc      * v_cc; v_den := v_den + v_cc; END IF;

    IF v_den = 0 THEN
        NEW.subject_average := NULL;
        RETURN NEW;
    END IF;

    NEW.subject_average := ROUND((v_num / v_den)::numeric, 2);
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.compute_grade_subject_average()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_term integer;
    v_class_subject_id uuid := new.class_subject_id;
    v_student_id uuid := new.student_id;
    v_d1 numeric;
    v_d2 numeric;
    v_ex numeric;
begin
    -- Determine the term from the assessment
    select term into v_term from public.assessments where id = new.assessment_id;
    if v_term is null then
        return new;
    end if;

    -- Look up D1, D2, Examen scores for this student/subject/term
    select g.score into v_d1
      from public.grades g
      join public.assessments a on a.id = g.assessment_id
     where g.student_id = v_student_id
       and g.class_subject_id = v_class_subject_id
       and a.term = v_term
       and a.kind = 'devoir_1';

    select g.score into v_d2
      from public.grades g
      join public.assessments a on a.id = g.assessment_id
     where g.student_id = v_student_id
       and g.class_subject_id = v_class_subject_id
       and a.term = v_term
       and a.kind = 'devoir_2';

    select g.score into v_ex
      from public.grades g
      join public.assessments a on a.id = g.assessment_id
     where g.student_id = v_student_id
       and g.class_subject_id = v_class_subject_id
       and a.term = v_term
       and a.kind = 'examen';

    -- BUG FIX (TIER 4): the lookups above only see rows ALREADY IN THE TABLE.
    -- When the completing mark (e.g. the examen) is being INSERTED, its own
    -- lookup returned NULL and the average was never computed — the compute
    -- path could only fire on a subsequent UPDATE. NEW's own score is now
    -- substituted for its kind so the average is set on the completing row.
    if new.assessment_id in (
        select id from public.assessments
         where term = v_term and kind = 'devoir_1'
           and class_subject_id = v_class_subject_id
    ) then
        v_d1 := new.score;
    elsif new.assessment_id in (
        select id from public.assessments
         where term = v_term and kind = 'devoir_2'
           and class_subject_id = v_class_subject_id
    ) then
        v_d2 := new.score;
    elsif new.assessment_id in (
        select id from public.assessments
         where term = v_term and kind = 'examen'
           and class_subject_id = v_class_subject_id
    ) then
        v_ex := new.score;
    end if;

    if v_d1 is not null and v_d2 is not null and v_ex is not null then
        new.subject_average := round(((v_d1 + v_d2 + 2 * v_ex) / 4.0)::numeric, 2);
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.compute_parent_summary(p_parent_id uuid, p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(parent_id uuid, total_outstanding numeric, total_overdue numeric, total_charged numeric, total_paid numeric, total_adjusted numeric, total_refunded numeric, total_cleared numeric, total_pending numeric, total_unallocated_credit numeric, account_count integer, accounts jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_accounts JSONB := '[]'::JSONB;
  v_total_outstanding NUMERIC := 0;
  v_total_overdue NUMERIC := 0;
  v_total_charged NUMERIC := 0;
  v_total_paid NUMERIC := 0;
  v_total_adjusted NUMERIC := 0;
  v_total_refunded NUMERIC := 0;
  v_total_cleared NUMERIC := 0;
  v_total_pending NUMERIC := 0;
  v_total_unallocated_credit NUMERIC := 0;
  v_account_count INT := 0;
  v_acc RECORD;
  v_latest_charge_due_date TIMESTAMPTZ;
BEGIN
  FOR v_acc IN
    SELECT
      le.account_id,
      le.category,
      le.student_id,
      SUM(le.amount) FILTER (WHERE le.at <= p_as_of) AS balance,
      COALESCE(SUM(le.amount) FILTER (WHERE le.entry_type = 'charge' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS charged,
      COALESCE(SUM(ABS(le.amount)) FILTER (WHERE le.entry_type = 'payment' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS paid,
      COALESCE(SUM(le.amount) FILTER (WHERE le.entry_type = 'adjustment' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS adjusted,
      COALESCE(SUM(ABS(le.amount)) FILTER (WHERE le.entry_type = 'refund' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS refunded,
      COALESCE(SUM(ABS(le.amount)) FILTER (WHERE le.entry_type = 'payment' AND le.payment_status = 'paid' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS cleared,
      COALESCE(SUM(ABS(le.amount)) FILTER (WHERE le.entry_type = 'payment' AND le.payment_status = 'pending' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS pending,
      COALESCE(SUM(le.amount) FILTER (WHERE le.entry_type = 'adjustment' AND le.category = 'parent_credit' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS unallocated_credit
    FROM ledger_entries le
    WHERE le.parent_id = p_parent_id
    GROUP BY le.account_id, le.category, le.student_id
  LOOP
    v_account_count := v_account_count + 1;

    -- Determine if the account is overdue — canonical mirror of the desktop
    -- engine's buildOverdueDueDateMap + computeParentSummary (INV-4 + INV-10,
    -- equivalence finding A-0042-OVERDUE):
    --   overdueDueDate[accountId] = MAX(charge.at) over ALL of the account's
    --   charge entries — NO as-of filter, NO reversal filter, and NO
    --   installment due_date JOIN (the app engines classify on the charge
    --   entry's own timestamp). The account is overdue iff
    --   balance > 0.001 DZD AND that latest-charge timestamp < p_as_of.
    SELECT MAX(le.at) INTO v_latest_charge_due_date
      FROM ledger_entries le
      WHERE le.account_id = v_acc.account_id
        AND le.entry_type = 'charge';

    DECLARE
      v_is_overdue BOOLEAN := (v_acc.balance > 0.001 AND v_latest_charge_due_date IS NOT NULL AND v_latest_charge_due_date < p_as_of);
    BEGIN
      v_accounts := v_accounts || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'accountId', v_acc.account_id,
        'category', v_acc.category,
        'studentId', v_acc.student_id,
        'balance', COALESCE(v_acc.balance, 0),
        'totalCharged', COALESCE(v_acc.charged, 0),
        'totalPaid', COALESCE(v_acc.paid, 0),
        'totalAdjusted', COALESCE(v_acc.adjusted, 0),
        'totalRefunded', COALESCE(v_acc.refunded, 0),
        'totalCleared', COALESCE(v_acc.cleared, 0),
        'totalPending', COALESCE(v_acc.pending, 0),
        'unallocatedCredit', COALESCE(v_acc.unallocated_credit, 0),
        'isOverdue', v_is_overdue
      ));

      v_total_outstanding := v_total_outstanding + COALESCE(v_acc.balance, 0);
      v_total_charged := v_total_charged + COALESCE(v_acc.charged, 0);
      v_total_paid := v_total_paid + COALESCE(v_acc.paid, 0);
      v_total_adjusted := v_total_adjusted + COALESCE(v_acc.adjusted, 0);
      v_total_refunded := v_total_refunded + COALESCE(v_acc.refunded, 0);
      v_total_cleared := v_total_cleared + COALESCE(v_acc.cleared, 0);
      v_total_pending := v_total_pending + COALESCE(v_acc.pending, 0);
      v_total_unallocated_credit := v_total_unallocated_credit + COALESCE(v_acc.unallocated_credit, 0);

      IF v_is_overdue THEN
        v_total_overdue := v_total_overdue + COALESCE(v_acc.balance, 0);
      END IF;
    END;
  END LOOP;

  RETURN QUERY
    SELECT
      p_parent_id,
      v_total_outstanding,
      v_total_overdue,
      v_total_charged,
      v_total_paid,
      v_total_adjusted,
      v_total_refunded,
      v_total_cleared,
      v_total_pending,
      v_total_unallocated_credit,
      v_account_count,
      v_accounts;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_direct_channel(p_other_profile_id uuid, p_name text DEFAULT NULL::text)
 RETURNS chat_channels
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_me     uuid := public.current_user_profile_id();
    v_tenant uuid := public.current_tenant_id();
    v_a      uuid;
    v_b      uuid;
    v_code   text;
    v_ch     public.chat_channels;
begin
    if v_me is null then
        raise exception 'create_direct_channel: no user profile for the caller (auth.uid() has no user_profiles row)'
            using errcode = '42501';
    end if;
    if v_tenant is null then
        raise exception 'create_direct_channel: caller has no tenant (global admins must act inside a tenant context)'
            using errcode = '42501';
    end if;
    -- T-400: the full STAFF role set (0023 census minus parent/student) —
    -- the workforce employee roles are staff; parents stay read+reply by
    -- design (their path is open_parent_admin_channel, 0067).
    if not public.has_any_role(array[
        'super_admin', 'manager', 'support_staff', 'financial_officer', 'teacher',
        'worker', 'buyer', 'driver', 'warehouse_worker'
    ]) then
        raise exception 'create_direct_channel: only staff may create chat channels (parents are read+reply by design)'
            using errcode = '42501';
    end if;
    if p_other_profile_id is null or p_other_profile_id = v_me then
        raise exception 'create_direct_channel: p_other_profile_id must be a different profile from the caller'
            using errcode = '22023';
    end if;
    -- The other member must be a real profile of the same tenant (or a
    -- global-admin profile). Guards against fabricated member ids.
    if not exists (
        select 1 from public.user_profiles up
         where up.id = p_other_profile_id
           and (up.tenant_id = v_tenant or up.tenant_id is null)
    ) then
        raise exception 'create_direct_channel: other profile not found in the caller''s tenant'
            using errcode = '22023';
    end if;

    v_a := least(v_me, p_other_profile_id);
    v_b := greatest(v_me, p_other_profile_id);
    v_code := 'DM-' || v_a || '-' || v_b;

    insert into public.chat_channels (
        tenant_id, code, name, channel_type, member_ids, created_by, description
    ) values (
        v_tenant, v_code, coalesce(nullif(btrim(p_name), ''), 'Direct'), 'direct',
        array[v_a, v_b], v_me, null
    )
    on conflict (tenant_id, code) do nothing
    returning * into v_ch;

    if v_ch is null then
        -- Already exists (idempotent re-open by either member of the pair).
        select * into v_ch
          from public.chat_channels
         where tenant_id = v_tenant and code = v_code;
    end if;

    if v_ch is null then
        raise exception 'create_direct_channel: channel vanished after upsert'
            using errcode = '22023';
    end if;

    -- Audit the creation (mock parity: chat.channel_create; convention 0014).
    if v_ch.created_by = v_me then
        insert into public.audit_logs (
            tenant_id, action, entity_type, entity_id, actor_id, after_json, note
        ) values (
            v_tenant, 'chat.channel_create', 'chat_channel', v_ch.id, v_me,
            to_jsonb(v_ch), 'create_direct_channel (idempotent RPC)'
        );
    end if;

    return v_ch;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_manual_debt(p_parent_id text, p_student_id text, p_category text, p_label text, p_amount_due numeric, p_due_date date, p_academic_year text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text)
 RETURNS TABLE(installment_id uuid, ledger_entry_id uuid, academic_year_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant      uuid := public.current_tenant_id();
    v_parent      uuid := public.resolve_parent_ref(v_tenant, p_parent_id);
    v_student     uuid := public.resolve_student_ref(v_tenant, p_student_id);
    v_label       text := nullif(btrim(coalesce(p_label, '')), '');
    v_note        text := nullif(btrim(coalesce(p_note, '')), '');
    v_reference   text := nullif(btrim(coalesce(p_reference, '')), '');
    v_year_id     uuid;
    v_ins_id      uuid;
    v_ledger_id   uuid;
    v_entry_no    text;
    v_description text;
    v_account_id  text;
begin
    -- Gate 1 — staff roles (the installments_admin policy's audience).
    if not public.has_any_role(array['super_admin', 'financial_officer', 'support_staff']) then
        raise exception 'forbidden: manual debt creation is a staff financial write';
    end if;

    -- Gate 2 — the refs must resolve (the upsert_installment_from_import errors).
    if v_parent is null then
        raise exception 'create_manual_debt: unresolvable parent ref %', p_parent_id;
    end if;
    if v_student is null then
        raise exception 'create_manual_debt: unresolvable student ref %', p_student_id;
    end if;

    -- Gate 3 — the contract guards (fail closed, before any write).
    if v_label is null or length(v_label) < 3 then
        raise exception 'create_manual_debt: the label (the reason) is required (>= 3 chars)';
    end if;
    if p_amount_due is null or p_amount_due <= 0 then
        raise exception 'create_manual_debt: the amount must be strictly positive';
    end if;
    if p_due_date is null then
        raise exception 'create_manual_debt: the due date is required';
    end if;
    if p_category is null or btrim(p_category) = '' then
        raise exception 'create_manual_debt: the category is required';
    end if;

    -- The academic-year stamp — the SAME precedence the import path applies
    -- (0127/0129): explicit code/label match first, then the INV-14 window
    -- resolver on the due date. Frozen at write time (ADR-030 / INV-18b).
    if p_academic_year is not null and nullif(btrim(p_academic_year), '') is not null then
        select ay.id into v_year_id
          from public.academic_years ay
         where ay.tenant_id = v_tenant
           and (ay.code = btrim(p_academic_year) or ay.label = btrim(p_academic_year))
         order by ay.start_date desc
         limit 1;
    end if;
    if v_year_id is null then
        v_year_id := public.resolve_academic_year_id_for_date(p_due_date, v_tenant);
    end if;

    -- The deterministic ledger identity (the led-{ISO}-{rand} convention).
    v_entry_no := 'led-' || to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
                  || '-' || substr(md5(gen_random_uuid()::text), 1, 8);

    v_description := 'Dette manuelle — ' || v_label
                     || (case when v_note is not null then ' · ' || v_note else '' end)
                     || (case when v_reference is not null then ' · réf. ' || v_reference else '' end);

    -- The charge lands on the student-scoped account when the debt is
    -- student-anchored (the adjust() R1.5 convention), else parent-scoped.
    v_account_id := 'parent:' || v_parent || ':category:' || p_category
                    || ':student:' || v_student;

    -- ------------------------------------------------------------------
    -- Write 1/3 — the INSTALLMENT row (the canonical debt record).
    -- ------------------------------------------------------------------
    v_ins_id := public.gen_uuid();
    insert into public.installments (
        id, tenant_id, parent_id, student_id, category, label,
        tranche_number, amount_due, amount_paid, amount_pending,
        due_date, paid_date, status,
        source_type, source_id,
        created_at, updated_at
    ) values (
        v_ins_id, v_tenant, v_parent, v_student, p_category, v_label,
        null, p_amount_due, 0, 0,
        p_due_date, null, 'unpaid',
        'manual_entry', 'manual-' || v_entry_no,
        now(), now()
    );

    -- ------------------------------------------------------------------
    -- Write 2/3 — the LEDGER charge entry (the billing-wire pattern: every
    -- new obligation is both an installment row and a charge entry).
    -- ------------------------------------------------------------------
    v_ledger_id := public.gen_uuid();
    insert into public.ledger_entries (
        id, tenant_id, entry_number, parent_id, student_id, account_id,
        entry_type, amount, category, description, entry_date,
        source_type, source_id, method, receipt_number, payment_status,
        reverses_id, actor_id, actor_name, at, metadata
    ) values (
        v_ledger_id, v_tenant, v_entry_no, v_parent, v_student, v_account_id,
        'charge', p_amount_due, p_category, v_description,
        (p_due_date::timestamptz at time zone 'UTC'),
        'manual_entry', 'manual-' || v_entry_no, null, null, null,
        null, p_actor_id::text, p_actor_name, now(),
        jsonb_build_object(
            'manual', true,
            'installmentId', v_ins_id,
            'note', v_note,
            'reference', v_reference,
            'reason', v_label,
            'source', 'create_manual_debt'
        )
    );

    -- ------------------------------------------------------------------
    -- Write 3/3 — the AUDIT row (the payment.collect pattern).
    -- ------------------------------------------------------------------
    insert into public.audit_logs (
        id, tenant_id, action, entity_type, entity_id, actor_id, actor_name,
        before_json, after_json, diff, note, created_at
    ) values (
        public.gen_uuid(), v_tenant, 'installment.manual_debt_created', 'installment', v_ins_id,
        p_actor_id, p_actor_name,
        null,
        jsonb_build_object(
            'installmentId', v_ins_id, 'ledgerEntryId', v_ledger_id,
            'parentId', v_parent, 'studentId', v_student,
            'category', p_category, 'label', v_label,
            'amountDue', p_amount_due, 'dueDate', p_due_date,
            'academicYearId', v_year_id, 'reference', v_reference
        ),
        jsonb_build_object(
            'installmentId', v_ins_id, 'ledgerEntryId', v_ledger_id,
            'parentId', v_parent, 'studentId', v_student,
            'category', p_category, 'label', v_label,
            'amountDue', p_amount_due, 'dueDate', p_due_date,
            'academicYearId', v_year_id, 'reference', v_reference
        ),
        'Dette manuelle créée via RPC create_manual_debt (T-466/DEBT-102 — la voie canonique)',
        now()
    );

    return query select v_ins_id, v_ledger_id, v_year_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.deactivate_fcm_tokens(p_user_id uuid, p_platform text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_caller_profile uuid;
    v_is_service_role boolean;
    v_deactivated integer;
BEGIN
    -- Same caller-verification rule as register_fcm_token.
    v_is_service_role := (auth.role() = 'service_role');
    IF NOT v_is_service_role THEN
        SELECT up.id INTO v_caller_profile
          FROM public.user_profiles up
         WHERE up.auth_user_id = auth.uid()
         LIMIT 1;
        IF v_caller_profile IS NULL OR v_caller_profile <> p_user_id THEN
            RAISE EXCEPTION 'deactivate_fcm_tokens: caller does not own user profile %', p_user_id
              USING ERRCODE = '42501';
        END IF;
    END IF;

    UPDATE public.device_tokens
       SET is_active = false,
           updated_at = now()
     WHERE user_id = p_user_id
       AND is_active = true
       AND (p_platform IS NULL OR platform = p_platform);

    GET DIAGNOSTICS v_deactivated = ROW_COUNT;
    RETURN v_deactivated;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_chat_read_by_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_profile uuid := public.current_user_profile_id();
    v_old jsonb := coalesce(old.read_by, '[]'::jsonb);
    v_new jsonb := coalesce(new.read_by, '[]'::jsonb);
begin
    -- Authors keep the full-update path governed by chat_messages_update_own
    -- (edit body, edited_at, deleted_at, attachments …). Nothing changes
    -- for them.
    if v_profile is not null and old.author_id = v_profile then
        return new;
    end if;

    -- Non-author (recipient) path: every column except read_by must be
    -- byte-identical. This is what stops a member from editing or deleting
    -- other people's messages through the new permissive policy.
    if new.tenant_id is distinct from old.tenant_id
       or new.channel_id is distinct from old.channel_id
       or new.author_id is distinct from old.author_id
       or new.body is distinct from old.body
       or new.edited_at is distinct from old.edited_at
       or new.edited_by is distinct from old.edited_by
       or new.deleted_at is distinct from old.deleted_at
       or new.parent_message_id is distinct from old.parent_message_id
       or new.attachments is distinct from old.attachments
       or new.sent_at is distinct from old.sent_at then
        raise exception 'chat_messages: non-author updates may only touch read_by (REALTIME-101)';
    end if;

    -- read_by must GROW by exactly one entry…
    if jsonb_array_length(v_new) <> jsonb_array_length(v_old) + 1 then
        raise exception 'chat_messages: read_by must grow by exactly one entry per update (REALTIME-101)';
    end if;

    -- …without removing or mutating any existing entry…
    if not (v_new @> v_old) then
        raise exception 'chat_messages: existing read_by entries may not be removed or modified (REALTIME-101)';
    end if;

    -- …and the appended entry must be the caller's OWN receipt.
    if not exists (
        select 1
        from jsonb_array_elements(v_new) e
        where e ->> 'user_id' = v_profile::text
          and not (v_old @> jsonb_build_array(e))
    ) then
        raise exception 'chat_messages: the appended read_by entry must belong to the caller (REALTIME-101)';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_staff_absence_justification_flow()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    -- is_excused may ONLY be set by the accepted decision (an already-excused
    -- absence keeps its flag through an admin re-request — the honest restart
    -- path accepted/rejected -> requested below). This check runs BEFORE the
    -- unchanged-status early return: setting is_excused WITHOUT a status
    -- change must be refused too (caught by the verify suite's 6e leg).
    if new.is_excused
       and old.justification_status <> 'accepted'
       and new.justification_status <> 'accepted' then
        raise exception 'staff_absences: is_excused requires justification_status = accepted';
    end if;

    if new.justification_status = old.justification_status then
        return new; -- unchanged status: field edits (notes) are allowed
    end if;

    if not (
        (old.justification_status = 'none'      and new.justification_status = 'requested')
     or (old.justification_status = 'requested' and new.justification_status = 'submitted')
     or (old.justification_status = 'submitted' and new.justification_status in ('accepted', 'rejected'))
     or (old.justification_status in ('accepted', 'rejected') and new.justification_status = 'requested')
    ) then
        raise exception 'staff_absences: illegal justification transition % -> % (allowed: none->requested->submitted->accepted|rejected)',
            old.justification_status, new.justification_status;
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.execute_batch_promotion(p_decisions jsonb, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_decision jsonb;
    v_student_id uuid;
    v_decision_code text;
    v_next_grade text;
    v_academic_year text;
    v_count integer := 0;
    v_updated_ids uuid[] := '{}';
    v_tenant uuid;
    v_caller_is_service_role boolean;
    v_student_found boolean;
    v_history_row public.student_academic_histories%ROWTYPE;
    v_valid_decisions text[] := ARRAY['promoted', 'repeated', 'graduated', 'transferred'];
    v_filiere_code text;
    v_specialite_code text;
BEGIN
    IF p_decisions IS NULL OR jsonb_typeof(p_decisions) <> 'array' THEN
        RAISE EXCEPTION 'execute_batch_promotion: p_decisions must be a JSON array'
          USING ERRCODE = '22023';
    END IF;

    v_caller_is_service_role := coalesce(auth.jwt() ->> 'role', '') = 'service_role';

    -- Tenant resolution + caller verification (same rule as 0059).
    v_tenant := public.current_tenant_id();
    IF p_tenant_id IS NOT NULL AND (v_tenant IS NULL OR p_tenant_id <> v_tenant) THEN
        IF NOT v_caller_is_service_role AND NOT public.is_global_admin() THEN
            RAISE EXCEPTION 'execute_batch_promotion: caller tenant mismatch (p_tenant_id=%)', p_tenant_id
              USING ERRCODE = '42501';
        END IF;
        v_tenant := p_tenant_id;
    END IF;

    IF v_tenant IS NULL THEN
        RAISE EXCEPTION 'execute_batch_promotion: caller tenant unresolvable'
          USING ERRCODE = '42501';
    END IF;

    FOR v_decision IN SELECT * FROM jsonb_array_elements(p_decisions)
    LOOP
        v_student_id     := (v_decision ->> 'student_id')::uuid;
        v_decision_code  := v_decision ->> 'decision';
        v_next_grade     := NULLIF(v_decision ->> 'next_grade_code', '');
        v_academic_year  := v_decision ->> 'academic_year';

        -- ── validation: fail the WHOLE batch on any bad decision ──
        IF v_student_id IS NULL THEN
            RAISE EXCEPTION 'execute_batch_promotion: decision entry without a valid student_id (%)', v_decision
              USING ERRCODE = '22023';
        END IF;
        IF v_decision_code IS NULL OR NOT (v_decision_code = ANY (v_valid_decisions)) THEN
            RAISE EXCEPTION 'execute_batch_promotion: invalid decision "%" for student %', v_decision_code, v_student_id
              USING ERRCODE = '22023';
        END IF;
        IF v_academic_year IS NULL OR v_academic_year = '' THEN
            RAISE EXCEPTION 'execute_batch_promotion: decision for student % lacks academic_year (the completed year to archive)', v_student_id
              USING ERRCODE = '22023';
        END IF;
        IF v_decision_code = 'promoted' AND v_next_grade IS NULL THEN
            RAISE EXCEPTION 'execute_batch_promotion: promoted decision for student % lacks next_grade_code', v_student_id
              USING ERRCODE = '22023';
        END IF;

        -- Student must exist in the caller's tenant (RLS hides foreign rows
        -- → v_student_found stays false → the batch fails closed). 0107 also
        -- reads the classification in force (stamped into the history row).
        SELECT TRUE, s.filiere_code, s.specialite_code
          INTO v_student_found, v_filiere_code, v_specialite_code
          FROM public.students s
         WHERE s.id = v_student_id
           AND s.tenant_id = v_tenant
           AND s.deleted_at IS NULL;

        IF v_student_found IS NOT TRUE THEN
            RAISE EXCEPTION 'execute_batch_promotion: student % not found in tenant %', v_student_id, v_tenant
              USING ERRCODE = '42501';
        END IF;

        -- ── 1. append-only history upsert (idempotent per student+year) ──
        -- 0107: filière/spécialité stamped from the student row (NOT from
        -- the payload — the server value is authoritative; the payload
        -- carries no classification).
        INSERT INTO public.student_academic_histories (
            tenant_id, student_id, academic_year, cycle, grade_code, grade_year,
            class_id, class_name, gpa, rank, decision, narrative,
            filiere_code, specialite_code
        ) VALUES (
            v_tenant, v_student_id, v_academic_year,
            v_decision ->> 'cycle', v_decision ->> 'grade_code',
            COALESCE((v_decision ->> 'grade_year')::int, 0),
            (v_decision ->> 'class_id')::uuid,
            v_decision ->> 'class_name',
            COALESCE((v_decision ->> 'gpa')::numeric, 0),
            (v_decision ->> 'rank')::int,
            v_decision_code,
            v_decision ->> 'narrative',
            v_filiere_code,
            v_specialite_code
        )
        ON CONFLICT (student_id, academic_year) DO UPDATE SET
            cycle       = EXCLUDED.cycle,
            grade_code  = EXCLUDED.grade_code,
            grade_year  = EXCLUDED.grade_year,
            class_id    = EXCLUDED.class_id,
            class_name  = EXCLUDED.class_name,
            gpa         = EXCLUDED.gpa,
            rank        = EXCLUDED.rank,
            decision    = EXCLUDED.decision,
            narrative   = EXCLUDED.narrative,
            filiere_code = EXCLUDED.filiere_code,
            specialite_code = EXCLUDED.specialite_code,
            recorded_at = now();

        -- ── 2 + 3. student advancement (desktop semantics preserved) ──
        IF v_decision_code = 'promoted' THEN
            UPDATE public.students
               SET grade_level_code = v_next_grade,
                   class_id = NULL,
                   updated_at = now()
             WHERE id = v_student_id
               AND tenant_id = v_tenant;
            v_updated_ids := v_updated_ids || v_student_id;
        ELSIF v_decision_code = 'graduated' THEN
            UPDATE public.students
               SET enrollment_status = 'graduated',
                   class_id = NULL,
                   updated_at = now()
             WHERE id = v_student_id
               AND tenant_id = v_tenant;
            v_updated_ids := v_updated_ids || v_student_id;
        END IF;
        -- 'repeated' / 'transferred': history row only — the student row
        -- is untouched (previous desktop contract preserved). The
        -- classification is likewise preserved (the stream continues into
        -- the repeated year unless the school edits it).

        v_count := v_count + 1;
    END LOOP;

    -- ── 4. one audit entry for the batch (0014 canonical entry point) ──
    PERFORM public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'student.promote',
        p_entity_type := 'student',
        p_entity_id   := NULL,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json  := jsonb_build_object(
                             'count', v_count,
                             'updated_student_ids', to_jsonb(v_updated_ids)
                         ),
        p_note        := 'Promotion de classe exécutée (atomique, RPC 0059/0107)'
    );

    RETURN jsonb_build_object(
        'processed_count', v_count,
        'updated_student_ids', to_jsonb(v_updated_ids)
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_calculate_student_term_gpa(p_student_id uuid, p_term text, p_academic_year text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_weighted_sum NUMERIC(10, 4) := 0;
    v_total_coef NUMERIC(10, 4) := 0;
    v_rec RECORD;
BEGIN
    FOR v_rec IN 
        SELECT 
            a.subject_average,
            a.coefficient
        FROM public.assessments a
        JOIN public.subjects s ON a.subject_id = s.id
        WHERE a.student_id = p_student_id
          AND a.term::text = p_term
          AND a.academic_year = p_academic_year
          AND a.subject_average IS NOT NULL
          AND s.is_extracurricular = FALSE
    LOOP
        v_weighted_sum := v_weighted_sum + (v_rec.subject_average * v_rec.coefficient);
        v_total_coef := v_total_coef + v_rec.coefficient;
    END LOOP;

    IF v_total_coef = 0 THEN
        RETURN NULL;
    END IF;

    RETURN ROUND((v_weighted_sum / v_total_coef)::NUMERIC, 2);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_cancel_promotion_cycle(p_cycle_id uuid, p_reason text DEFAULT NULL::text, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_cycle_tenant(p_tenant_id);
    v_cycle public.promotion_cycles;
begin
    select * into v_cycle
      from public.promotion_cycles pc
     where pc.id = p_cycle_id and pc.tenant_id = v_tenant
     for update;
    if v_cycle.id is null then
        raise exception 'fn_cancel_promotion_cycle: cycle % not found in tenant', p_cycle_id
          using errcode = '23503';
    end if;
    if v_cycle.status = 'completed' then
        raise exception 'fn_cancel_promotion_cycle: the cycle for % is completed — it cannot be cancelled (its history is immutable)', v_cycle.source_academic_year
          using errcode = '55006';
    end if;
    if v_cycle.status = 'cancelled' then
        raise exception 'fn_cancel_promotion_cycle: the cycle for % is already cancelled', v_cycle.source_academic_year
          using errcode = '55006';
    end if;

    update public.promotion_cycles pc
       set status = 'cancelled',
           notes = coalesce(p_reason, notes),
           updated_at = now()
     where pc.id = p_cycle_id;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'promotion.cycle_cancel',
        p_entity_type := 'promotion_cycle',
        p_entity_id   := p_cycle_id,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json   := jsonb_build_object('reason', p_reason),
        p_note         := format('Cycle de promotion %s → %s ANNULÉ.', v_cycle.source_academic_year, v_cycle.target_academic_year)
    );

    return jsonb_build_object('ok', true, 'cycle_id', p_cycle_id, 'status', 'cancelled');
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_complete_promotion_cycle(p_cycle_id uuid, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_cycle_tenant(p_tenant_id);
    v_cycle public.promotion_cycles;
    v_pending text;
begin
    select * into v_cycle
      from public.promotion_cycles pc
     where pc.id = p_cycle_id and pc.tenant_id = v_tenant
     for update;
    if v_cycle.id is null then
        raise exception 'fn_complete_promotion_cycle: cycle % not found in tenant', p_cycle_id
          using errcode = '23503';
    end if;
    if v_cycle.status = 'completed' then
        raise exception 'fn_complete_promotion_cycle: the cycle for % is already completed', v_cycle.source_academic_year
          using errcode = '55006';
    end if;
    if v_cycle.status = 'cancelled' then
        raise exception 'fn_complete_promotion_cycle: the cycle for % is cancelled — it cannot be completed', v_cycle.source_academic_year
          using errcode = '55006';
    end if;

    -- EVERY class must be processed / exception / skipped.
    select string_agg(pcc.class_name, ', ') into v_pending
      from public.promotion_cycle_classes pcc
     where pcc.cycle_id = p_cycle_id
       and pcc.status not in ('processed', 'exception', 'skipped');
    if v_pending is not null then
        raise exception 'fn_complete_promotion_cycle: le cycle ne peut pas être terminé — classes restant à traiter : %', v_pending
          using errcode = '22023';
    end if;

    update public.promotion_cycles pc
       set status = 'completed',
           completed_at = now(),
           completed_by_name = coalesce(p_actor_name, '—'),
           updated_at = now()
     where pc.id = p_cycle_id
    returning * into v_cycle;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'promotion.cycle_complete',
        p_entity_type := 'promotion_cycle',
        p_entity_id   := p_cycle_id,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json   := (select jsonb_build_object(
                               'source_academic_year', pc.source_academic_year,
                               'target_academic_year', pc.target_academic_year,
                               'classes', (select count(*) from public.promotion_cycle_classes pcc where pcc.cycle_id = pc.id),
                               'promoted', (select coalesce(sum(pcc.promoted_count), 0) from public.promotion_cycle_classes pcc where pcc.cycle_id = pc.id),
                               'repeated', (select coalesce(sum(pcc.repeating_count), 0) from public.promotion_cycle_classes pcc where pcc.cycle_id = pc.id)
                           ) from public.promotion_cycles pc where pc.id = p_cycle_id),
        p_note         := format('Cycle de promotion %s → %s TERMINÉ.', v_cycle.source_academic_year, v_cycle.target_academic_year)
    );

    return jsonb_build_object(
        'ok', true,
        'cycle_id', p_cycle_id,
        'status', 'completed'
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_create_promotion_cycle(p_source_academic_year text, p_target_academic_year text DEFAULT NULL::text, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_cycle_tenant(p_tenant_id);
    v_source_year public.academic_years;
    v_target text;
    v_cycle public.promotion_cycles;
    v_count integer;
    v_classes integer;
begin
    if p_source_academic_year is null or btrim(p_source_academic_year) = '' then
        raise exception 'fn_create_promotion_cycle: p_source_academic_year is required'
          using errcode = '22023';
    end if;

    -- The source year must exist in the tenant (by code OR label — the
    -- fn_finalize_class_placements resolution convention).
    select * into v_source_year
      from public.academic_years ay
     where ay.tenant_id = v_tenant
       and (ay.code = p_source_academic_year or ay.label = p_source_academic_year)
     order by ay.is_current desc, ay.start_date desc
     limit 1;
    if v_source_year.id is null then
        raise exception 'fn_create_promotion_cycle: source academic year "%" not found in tenant (create it in Années scolaires first)', p_source_academic_year
          using errcode = '23503';
    end if;

    -- The target year defaults to source + 1 ("2026-2027" → "2027-2028").
    v_target := coalesce(nullif(btrim(p_target_academic_year), ''),
                         (regexp_replace(v_source_year.code, '^\d{4}', (substring(v_source_year.code from 1 for 4)::int + 1)::text)));
    if v_target is null or v_target = v_source_year.code then
        raise exception 'fn_create_promotion_cycle: target year "%" must differ from the source year "%"', coalesce(v_target, '(null)'), v_source_year.code
          using errcode = '22023';
    end if;

    -- ONE active cycle per source year (cancelled ones free the slot).
    select count(*) into v_count
      from public.promotion_cycles pc
     where pc.tenant_id = v_tenant
       and pc.source_academic_year = v_source_year.code
       and pc.status <> 'cancelled';
    if v_count > 0 then
        raise exception 'fn_create_promotion_cycle: an active cycle already exists for the year % (open it instead of creating a second one)', v_source_year.code
          using errcode = '23505';
    end if;

    insert into public.promotion_cycles (
        tenant_id, source_academic_year, target_academic_year, status,
        created_by_profile_id, created_by_name
    ) values (
        v_tenant, v_source_year.code, v_target, 'draft',
        p_actor_profile_id, coalesce(p_actor_name, '—')
    )
    returning * into v_cycle;

    -- Enumerate the source year's classes with their LIVE student counts.
    insert into public.promotion_cycle_classes (
        tenant_id, cycle_id, class_id, class_code, class_name, grade_code,
        status, students_awaiting
    )
    select v_tenant, v_cycle.id, c.id, c.code, coalesce(c.name, c.code),
           coalesce(c.grade_code, '?'), 'pending',
           (select count(*) from public.students s
             where s.class_id = c.id
               and s.tenant_id = v_tenant
               and s.deleted_at is null
               and s.is_active)
      from public.classes c
     where c.tenant_id = v_tenant
       and c.academic_year_id = v_source_year.id
       and c.is_active;

    select count(*) into v_classes
      from public.promotion_cycle_classes pcc
     where pcc.cycle_id = v_cycle.id;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'promotion.cycle_create',
        p_entity_type := 'promotion_cycle',
        p_entity_id   := v_cycle.id,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json   := jsonb_build_object(
                             'source_academic_year', v_cycle.source_academic_year,
                             'target_academic_year', v_cycle.target_academic_year,
                             'classes', v_classes
                         ),
        p_note         := format('Cycle de promotion créé pour %s → %s : %s classe(s) à examiner.', v_cycle.source_academic_year, v_cycle.target_academic_year, v_classes)
    );

    return jsonb_build_object(
        'ok', true,
        'cycle_id', v_cycle.id,
        'source_academic_year', v_cycle.source_academic_year,
        'target_academic_year', v_cycle.target_academic_year,
        'classes_count', v_classes
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_deterministic_activation_code(p_parent_code text, p_tenant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
    identity text := btrim(coalesce(p_tenant_id::text, '') || '|' || coalesce(p_parent_code, ''));
    h bigint;
begin
    if identity = '' then
        return '000000';
    end if;
    h := public.fn_fnv1a(identity);
    return ((h % 900000) + 100000)::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_deterministic_parent_code(p_year integer, p_phone text DEFAULT NULL::text, p_display_name text DEFAULT NULL::text, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_fallback_seed text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
    parts text[] := array[]::text[];
    identity text;
begin
    -- Canonical rule: per-field trim, DROP empty fields, join with '|'.
    if coalesce(btrim(p_phone), '') <> '' then parts := parts || btrim(p_phone); end if;
    if coalesce(btrim(p_display_name), '') <> '' then parts := parts || btrim(p_display_name); end if;
    if coalesce(btrim(p_first_name), '') <> '' then parts := parts || btrim(p_first_name); end if;
    if coalesce(btrim(p_last_name), '') <> '' then parts := parts || btrim(p_last_name); end if;
    identity := array_to_string(parts, '|');
    -- T-018 rule: NO random fallback — empty identity uses the stable seed.
    if identity = '' then
        identity := coalesce(nullif(btrim(p_fallback_seed), ''), 'orphan-parent');
    end if;
    return 'PAR-' || p_year::text || '-' || public.fn_stable_hash(identity);
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_er_decide_proposal(p_proposal_id text, p_decision text, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_rationale text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant    uuid;
    v_proposal  public.er_match_proposals;
    v_event_id  uuid;
    v_edge      public.er_identity_edges;
begin
    -- 0. Tenant + guards (T-439/SEC-115: the 0128 caller-tenant-mismatch
    --    guard — the experimental flag was never an authorization boundary,
    --    and SECURITY DEFINER bypasses the er_* RLS by construction).
    v_tenant := public.fn_er_resolve_tenant(p_tenant_id);
    if p_decision not in ('approve', 'reject') then
        raise exception 'fn_er_decide_proposal: décision invalide (%)', p_decision;
    end if;

    select * into v_proposal
    from public.er_match_proposals
    where id = p_proposal_id and tenant_id = v_tenant
    for update;

    if not found then
        raise exception 'fn_er_decide_proposal: proposition introuvable (%)', p_proposal_id;
    end if;
    if v_proposal.status <> 'proposed' then
        raise exception 'fn_er_decide_proposal: proposition déjà décidée (statut %)', v_proposal.status
            using hint = 'A decided proposal is immutable — the audit trail is the correction path.';
    end if;

    -- 1. The edge: active on approve, negative on reject.
    --    A pre-existing negative edge means the pair was rejected before —
    --    refuse the approval (the review queue never re-proposes it anyway).
    select * into v_edge
    from public.er_identity_edges
    where tenant_id = v_tenant
      and a_observation_key = v_proposal.a_observation_key
      and b_observation_key = v_proposal.b_observation_key;

    if p_decision = 'reject' then
        insert into public.er_identity_edges as e (
            tenant_id, a_observation_key, b_observation_key, confidence, status,
            evidence, created_by
        ) values (
            v_tenant, v_proposal.a_observation_key, v_proposal.b_observation_key,
            v_proposal.confidence, 'negative',
            v_proposal.evidence, p_actor_id
        )
        on conflict (tenant_id, a_observation_key, b_observation_key)
        do update set status = 'negative', severed_at = null, severed_by = null;

        update public.er_match_proposals
        set status = 'rejected', decided_by = p_actor_id,
            decided_by_name = p_actor_name, decided_at = now(), rationale = p_rationale
        where id = p_proposal_id and tenant_id = v_tenant;

        insert into public.er_aggregation_events (
            tenant_id, event_type, run_id, canonical_id, observation_keys,
            actor_id, actor_name, rationale, payload
        ) values (
            v_tenant, 'PROPOSAL_REJECTED', v_proposal.run_id, v_proposal.b_canonical_id,
            array[v_proposal.a_observation_key, v_proposal.b_observation_key],
            p_actor_id, p_actor_name, p_rationale,
            jsonb_build_object('proposalId', p_proposal_id, 'confidence', v_proposal.confidence,
                               'band', v_proposal.band)
        ) returning id into v_event_id;

    else
        if v_edge.status = 'negative' then
            raise exception 'fn_er_decide_proposal: paire déjà rejetée (contrainte négative)'
                using hint = 'Un-reject explicitly via the review surface first.';
        end if;

        insert into public.er_identity_edges as e (
            tenant_id, a_observation_key, b_observation_key, confidence, status,
            evidence, created_by
        ) values (
            v_tenant, v_proposal.a_observation_key, v_proposal.b_observation_key,
            v_proposal.confidence, 'active',
            v_proposal.evidence, p_actor_id
        )
        on conflict (tenant_id, a_observation_key, b_observation_key)
        do update set status = 'active', confidence = excluded.confidence,
                      evidence = excluded.evidence, severed_at = null, severed_by = null;

        update public.er_match_proposals
        set status = 'approved', decided_by = p_actor_id,
            decided_by_name = p_actor_name, decided_at = now(), rationale = p_rationale
        where id = p_proposal_id and tenant_id = v_tenant;

        insert into public.er_aggregation_events (
            tenant_id, event_type, run_id, canonical_id, observation_keys,
            actor_id, actor_name, rationale, payload
        ) values (
            v_tenant, 'PROPOSAL_APPROVED', v_proposal.run_id, v_proposal.b_canonical_id,
            array[v_proposal.a_observation_key, v_proposal.b_observation_key],
            p_actor_id, p_actor_name, p_rationale,
            jsonb_build_object('proposalId', p_proposal_id, 'confidence', v_proposal.confidence,
                               'band', v_proposal.band)
        ) returning id into v_event_id;
    end if;

    -- 2. Audit (the canonical trail).
    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'er.decide_proposal',
        p_entity_type := 'er_match_proposal',
        p_entity_id   := null,
        p_actor_id    := p_actor_id,
        p_actor_name  := p_actor_name,
        p_after_json  := jsonb_build_object(
                             'proposalId', p_proposal_id,
                             'decision', p_decision,
                             'confidence', v_proposal.confidence,
                             'band', v_proposal.band
                         ),
        p_note        := format('ER-PMAE : proposition %s — décision %s (confiance %s).',
                                p_proposal_id, p_decision, v_proposal.confidence)
    );

    return jsonb_build_object(
        'eventId', v_event_id,
        'proposalId', p_proposal_id,
        'status', case when p_decision = 'approve' then 'approved' else 'rejected' end
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_er_has_aggregation_state(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant uuid;
begin
    -- T-439 (SEC-115): the caller-tenant guard (read-only surface, same
    -- boundary as the mutators).
    v_tenant := public.fn_er_resolve_tenant(p_tenant_id);
    return exists (
        select 1 from public.er_match_proposals
        where tenant_id = v_tenant
          and status <> 'proposed'
    ) or exists (
        select 1 from public.er_identity_edges
        where tenant_id = v_tenant
          and status = 'active'
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_er_merge_parents(p_target_parent_id uuid, p_source_parent_id uuid, p_proposal_id text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_rationale text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant       uuid;
    v_target       public.parents;
    v_source       public.parents;
    v_event_id     uuid;
    v_students     jsonb := '{}'::jsonb;
    v_payments     jsonb := '{}'::jsonb;
    v_installments jsonb := '{}'::jsonb;
    v_ledger       jsonb := '{}'::jsonb;
    v_row          record;
begin
    -- 0. Tenant + guards (T-439/SEC-115: the 0128 caller-tenant-mismatch
    --    guard — the experimental flag was never an authorization boundary,
    --    and SECURITY DEFINER bypasses the er_* RLS by construction).
    v_tenant := public.fn_er_resolve_tenant(p_tenant_id);
    if p_target_parent_id is null or p_source_parent_id is null
       or p_target_parent_id = p_source_parent_id then
        raise exception 'fn_er_merge_parents: cible et source requis et distincts';
    end if;

    select * into v_target from public.parents
    where id = p_target_parent_id and tenant_id = v_tenant;
    select * into v_source from public.parents
    where id = p_source_parent_id and tenant_id = v_tenant;

    if v_target.id is null or v_source.id is null then
        raise exception 'fn_er_merge_parents: parent introuvable (cible ou source)';
    end if;
    if v_source.deleted_at is not null then
        raise exception 'fn_er_merge_parents: la source est déjà fusionnée/supprimée (deleted_at non nul)'
            using hint = 'Un-merge the prior merge first.';
    end if;

    -- 1. Capture the COMPLETE prior mapping (the restore contract), then
    --    re-point each relationship table (INV-54: re-point, never rewrite).
    for v_row in
        select id from public.students
        where tenant_id = v_tenant and parent_id = p_source_parent_id
        for update
    loop
        v_students := v_students || jsonb_build_object(v_row.id::text, p_source_parent_id::text);
    end loop;
    update public.students
    set parent_id = p_target_parent_id
    where tenant_id = v_tenant and parent_id = p_source_parent_id;

    for v_row in
        select id from public.payments
        where tenant_id = v_tenant and parent_id = p_source_parent_id
        for update
    loop
        v_payments := v_payments || jsonb_build_object(v_row.id::text, p_source_parent_id::text);
    end loop;
    update public.payments
    set parent_id = p_target_parent_id
    where tenant_id = v_tenant and parent_id = p_source_parent_id;

    for v_row in
        select id from public.installments
        where tenant_id = v_tenant and parent_id = p_source_parent_id
        for update
    loop
        v_installments := v_installments || jsonb_build_object(v_row.id::text, p_source_parent_id::text);
    end loop;
    update public.installments
    set parent_id = p_target_parent_id
    where tenant_id = v_tenant and parent_id = p_source_parent_id;

    for v_row in
        select id from public.ledger_entries
        where tenant_id = v_tenant and parent_id = p_source_parent_id
        for update
    loop
        v_ledger := v_ledger || jsonb_build_object(v_row.id::text, p_source_parent_id::text);
    end loop;
    update public.ledger_entries
    set parent_id = p_target_parent_id
    where tenant_id = v_tenant and parent_id = p_source_parent_id;

    -- 2. Soft-delete the merged-away parent (the T-384 convention).
    update public.parents
    set deleted_at = now()
    where id = p_source_parent_id and tenant_id = v_tenant;

    -- 3. The append-only event carrying the COMPLETE prior mapping.
    insert into public.er_aggregation_events (
        tenant_id, event_type, run_id, canonical_id, merged_away_id,
        observation_keys, actor_id, actor_name, rationale, payload
    ) values (
        v_tenant, 'MERGE_EXECUTED', null, p_target_parent_id, p_source_parent_id,
        '{}', p_actor_id, p_actor_name, p_rationale,
        jsonb_build_object(
            'proposalId', p_proposal_id,
            'restoreMapping', jsonb_build_object(
                'students', v_students,
                'payments', v_payments,
                'installments', v_installments,
                'ledger_entries', v_ledger
            )
        )
    ) returning id into v_event_id;

    -- 4. Audit (the canonical trail).
    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'er.merge_parents',
        p_entity_type := 'parent',
        p_entity_id   := p_target_parent_id,
        p_actor_id    := p_actor_id,
        p_actor_name  := p_actor_name,
        p_before_json := jsonb_build_object(
                             'sourceParentId', p_source_parent_id,
                             'sourceParentCode', v_source.parent_code
                         ),
        p_after_json  := jsonb_build_object(
                             'targetParentId', p_target_parent_id,
                             'targetParentCode', v_target.parent_code,
                             'eventId', v_event_id,
                             'rePointed', jsonb_build_object(
                                 'students', (select count(*) from jsonb_object_keys(v_students)),
                                 'payments', (select count(*) from jsonb_object_keys(v_payments)),
                                 'installments', (select count(*) from jsonb_object_keys(v_installments)),
                                 'ledger_entries', (select count(*) from jsonb_object_keys(v_ledger))
                             )
                         ),
        p_note        := format('ER-PMAE : fusion réversible du parent %s dans %s (%s) — mappage complet enregistré (événement %s).',
                                v_source.parent_code, v_target.parent_code,
                                coalesce(p_rationale, 'décision humaine'), v_event_id)
    );

    return jsonb_build_object(
        'eventId', v_event_id,
        'targetParentId', p_target_parent_id,
        'sourceParentId', p_source_parent_id,
        'rePointed', jsonb_build_object(
            'students', v_students,
            'payments', v_payments,
            'installments', v_installments,
            'ledger_entries', v_ledger
        )
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_er_resolve_tenant(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_tenant uuid;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    v_tenant := public.current_tenant_id();
    if p_tenant_id is not null and (v_tenant is null or p_tenant_id <> v_tenant) then
        if not v_caller_is_service_role and not public.is_global_admin() then
            raise exception 'er-pmae: caller tenant mismatch (p_tenant_id=%)', p_tenant_id
              using errcode = '42501';
        end if;
        v_tenant := p_tenant_id;
    end if;
    if v_tenant is null then
        raise exception 'er-pmae: caller tenant unresolvable'
          using errcode = '42501';
    end if;
    return v_tenant;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_er_unmerge_parents(p_event_id uuid, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_rationale text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant      uuid;
    v_event       public.er_aggregation_events;
    v_restore     jsonb;
    v_row_id      uuid;
    v_prev_parent uuid;
    v_counts      jsonb;
    v_undone_id   uuid;
begin
    -- 0. Tenant + guards (T-439/SEC-115: the 0128 caller-tenant-mismatch
    --    guard — the experimental flag was never an authorization boundary,
    --    and SECURITY DEFINER bypasses the er_* RLS by construction).
    v_tenant := public.fn_er_resolve_tenant(p_tenant_id);

    select * into v_event
    from public.er_aggregation_events
    where id = p_event_id and tenant_id = v_tenant and event_type = 'MERGE_EXECUTED';

    if v_event.id is null then
        raise exception 'fn_er_unmerge_parents: événement de fusion introuvable (%)', p_event_id;
    end if;

    -- One unmerge per merge (idempotence of the reversal).
    if exists (
        select 1 from public.er_aggregation_events
        where tenant_id = v_tenant and event_type = 'MERGE_UNDONE'
          and payload->>'reversesEventId' = p_event_id::text
    ) then
        raise exception 'fn_er_unmerge_parents: cette fusion est déjà annulée';
    end if;

    v_restore := v_event.payload->'restoreMapping';

    -- 1. Replay the prior mapping (only rows that STILL point at the target
    --    from this merge — a row re-parented since is left alone, honestly).
    --    0131 FIX: a direct jsonb→uuid cast raises 42846, and value::text
    --    keeps the JSON quotes — the unquoted extraction is `#>> '{}'`
    --    (the KEY is already unquoted text).
    if v_restore->'students' is not null then
        for v_row_id, v_prev_parent in
            select key::uuid, (value #>> '{}')::uuid
            from jsonb_each(v_restore->'students')
        loop
            update public.students
            set parent_id = v_prev_parent
            where id = v_row_id and tenant_id = v_tenant
              and parent_id = v_event.canonical_id;
        end loop;
    end if;
    if v_restore->'payments' is not null then
        for v_row_id, v_prev_parent in
            select key::uuid, (value #>> '{}')::uuid
            from jsonb_each(v_restore->'payments')
        loop
            update public.payments
            set parent_id = v_prev_parent
            where id = v_row_id and tenant_id = v_tenant
              and parent_id = v_event.canonical_id;
        end loop;
    end if;
    if v_restore->'installments' is not null then
        for v_row_id, v_prev_parent in
            select key::uuid, (value #>> '{}')::uuid
            from jsonb_each(v_restore->'installments')
        loop
            update public.installments
            set parent_id = v_prev_parent
            where id = v_row_id and tenant_id = v_tenant
              and parent_id = v_event.canonical_id;
        end loop;
    end if;
    if v_restore->'ledger_entries' is not null then
        for v_row_id, v_prev_parent in
            select key::uuid, (value #>> '{}')::uuid
            from jsonb_each(v_restore->'ledger_entries')
        loop
            update public.ledger_entries
            set parent_id = v_prev_parent
            where id = v_row_id and tenant_id = v_tenant
              and parent_id = v_event.canonical_id;
        end loop;
    end if;

    -- 2. Restore the merged-away parent (un-soft-delete).
    update public.parents
    set deleted_at = null
    where id = v_event.merged_away_id and tenant_id = v_tenant;

    -- 3. Sever the identity edges tied to the merged-away canonical entity.
    update public.er_identity_edges
    set status = 'severed', severed_at = now(), severed_by = p_actor_id
    where tenant_id = v_tenant and status = 'active'
      and (a_observation_key = 'canonical:' || v_event.merged_away_id::text
           or b_observation_key = 'canonical:' || v_event.merged_away_id::text);

    -- 4. The MERGE_UNDONE event (referencing the reversed merge).
    insert into public.er_aggregation_events (
        tenant_id, event_type, run_id, canonical_id, merged_away_id,
        observation_keys, actor_id, actor_name, rationale, payload
    ) values (
        v_tenant, 'MERGE_UNDONE', v_event.run_id, v_event.canonical_id, v_event.merged_away_id,
        v_event.observation_keys, p_actor_id, p_actor_name, p_rationale,
        jsonb_build_object('reversesEventId', p_event_id::text)
    ) returning id into v_undone_id;

    -- 5. Audit.
    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'er.unmerge_parents',
        p_entity_type := 'parent',
        p_entity_id   := v_event.merged_away_id,
        p_actor_id    := p_actor_id,
        p_actor_name  := p_actor_name,
        p_before_json := jsonb_build_object('mergeEventId', p_event_id),
        p_after_json  := jsonb_build_object('undoneEventId', v_undone_id,
                                            'restoredParentId', v_event.merged_away_id),
        p_note        := format('ER-PMAE : annulation de la fusion %s — mappage restauré, parent %s rétabli.',
                                p_event_id, v_event.merged_away_id)
    );

    select jsonb_build_object(
        'students', (select count(*) from jsonb_object_keys(coalesce(v_restore->'students', '{}'::jsonb))),
        'payments', (select count(*) from jsonb_object_keys(coalesce(v_restore->'payments', '{}'::jsonb))),
        'installments', (select count(*) from jsonb_object_keys(coalesce(v_restore->'installments', '{}'::jsonb))),
        'ledger_entries', (select count(*) from jsonb_object_keys(coalesce(v_restore->'ledger_entries', '{}'::jsonb)))
    ) into v_counts;

    return jsonb_build_object(
        'eventId', v_undone_id,
        'restoredParentId', v_event.merged_away_id,
        'restored', v_counts
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_finalize_class_placements(p_target_year_id uuid DEFAULT NULL::uuid, p_target_year_code text DEFAULT NULL::text, p_new_classes jsonb DEFAULT '[]'::jsonb, p_updated_classes jsonb DEFAULT '[]'::jsonb, p_student_assignments jsonb DEFAULT '[]'::jsonb, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_class_record jsonb;
    v_student_record jsonb;
    v_update_record jsonb;
    v_tenant uuid;
    v_caller_is_service_role boolean;
    v_target_year public.academic_years;
    v_academic_level_id uuid;
    v_created_class_id uuid;
    v_created_classes_map jsonb := '{}'::jsonb;
    v_final_target_class_id uuid;
    v_target_class_grade text;
    v_class_found boolean;
    v_class_filiere text;
    v_class_specialite text;
    v_filiere_code text;
    v_specialite_code text;
    v_student_filiere text;
    v_student_specialite text;
    v_created_classes_count integer := 0;
    v_updated_classes_count integer := 0;
    v_assigned_students_count integer := 0;
    v_draft_id text;
    v_code text;
BEGIN
    IF p_new_classes IS NULL OR jsonb_typeof(p_new_classes) <> 'array' THEN
        RAISE EXCEPTION 'fn_finalize_class_placements: p_new_classes must be a JSON array'
          USING ERRCODE = '22023';
    END IF;
    IF p_updated_classes IS NULL OR jsonb_typeof(p_updated_classes) <> 'array' THEN
        RAISE EXCEPTION 'fn_finalize_class_placements: p_updated_classes must be a JSON array'
          USING ERRCODE = '22023';
    END IF;
    IF p_student_assignments IS NULL OR jsonb_typeof(p_student_assignments) <> 'array' THEN
        RAISE EXCEPTION 'fn_finalize_class_placements: p_student_assignments must be a JSON array'
          USING ERRCODE = '22023';
    END IF;

    v_caller_is_service_role := coalesce(auth.jwt() ->> 'role', '') = 'service_role';

    -- Tenant resolution + caller verification (0055/0059 pattern).
    v_tenant := public.current_tenant_id();
    IF p_tenant_id IS NOT NULL AND (v_tenant IS NULL OR p_tenant_id <> v_tenant) THEN
        IF NOT v_caller_is_service_role AND NOT public.is_global_admin() THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: caller tenant mismatch (p_tenant_id=%)', p_tenant_id
              USING ERRCODE = '42501';
        END IF;
        v_tenant := p_tenant_id;
    END IF;

    IF v_tenant IS NULL THEN
        RAISE EXCEPTION 'fn_finalize_class_placements: caller tenant unresolvable'
          USING ERRCODE = '42501';
    END IF;

    -- ── target academic year: by id when a UUID is supplied, else by code ──
    IF p_target_year_id IS NOT NULL THEN
        SELECT * INTO v_target_year
          FROM public.academic_years ay
         WHERE ay.id = p_target_year_id
           AND ay.tenant_id = v_tenant;
    END IF;
    IF v_target_year.id IS NULL AND p_target_year_code IS NOT NULL AND p_target_year_code <> '' THEN
        SELECT * INTO v_target_year
          FROM public.academic_years ay
         WHERE ay.tenant_id = v_tenant
           AND (ay.code = p_target_year_code OR ay.label = p_target_year_code)
         ORDER BY ay.is_current DESC, ay.start_date DESC
         LIMIT 1;
    END IF;
    IF v_target_year.id IS NULL THEN
        RAISE EXCEPTION 'fn_finalize_class_placements: target academic year "%" not found in tenant (create it in Années scolaires first)', coalesce(p_target_year_code, p_target_year_id::text)
          USING ERRCODE = '23503';
    END IF;

    -- ── Step A: insert the newly drafted classes ──────────────────────────
    FOR v_class_record IN SELECT * FROM jsonb_array_elements(p_new_classes)
    LOOP
        v_draft_id := NULLIF(v_class_record ->> 'clientDraftId', '');
        v_code := NULLIF(v_class_record ->> 'code', '');

        IF NULLIF(v_class_record ->> 'name', '') IS NULL THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: new class draft % lacks a name', v_class_record
              USING ERRCODE = '22023';
        END IF;
        IF NULLIF(v_class_record ->> 'gradeCode', '') IS NULL THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: new class draft "%" lacks a gradeCode', v_class_record ->> 'name'
              USING ERRCODE = '22023';
        END IF;
        IF v_code IS NULL THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: new class draft "%" lacks a code', v_class_record ->> 'name'
              USING ERRCODE = '22023';
        END IF;

        -- academic_level_id RESOLVED from academic_levels.grade_code (the
        -- column is a real UUID FK — never synthesized).
        SELECT al.id INTO v_academic_level_id
          FROM public.academic_levels al
         WHERE al.tenant_id = v_tenant
           AND al.grade_code = v_class_record ->> 'gradeCode';
        IF v_academic_level_id IS NULL THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: no academic_level for grade_code "%" (tenant %)', v_class_record ->> 'gradeCode', v_tenant
              USING ERRCODE = '23503';
        END IF;

        -- T-401: classification codes validated against the tenant catalog
        -- when provided (NULL = untagged, the pre-0107 default).
        v_filiere_code := lower(NULLIF(btrim(v_class_record ->> 'filiereCode'), ''));
        v_specialite_code := lower(NULLIF(btrim(v_class_record ->> 'specialiteCode'), ''));
        IF v_filiere_code IS NOT NULL THEN
            IF NOT EXISTS (SELECT 1 FROM public.filieres f
                            WHERE f.tenant_id = v_tenant AND f.code = v_filiere_code
                              AND f.parent_code IS NULL AND f.is_active) THEN
                RAISE EXCEPTION 'fn_finalize_class_placements: unknown filiere_code "%" for tenant (draft "%")', v_filiere_code, v_class_record ->> 'name'
                  USING ERRCODE = '23503';
            END IF;
            IF v_filiere_code = 'general' AND v_specialite_code IS NOT NULL THEN
                RAISE EXCEPTION 'fn_finalize_class_placements: a general class cannot carry a specialite (draft "%")', v_class_record ->> 'name'
                  USING ERRCODE = '22023';
            END IF;
            IF v_specialite_code IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.filieres f
                                                              WHERE f.tenant_id = v_tenant AND f.code = v_specialite_code
                                                                AND f.parent_code = v_filiere_code AND f.is_active) THEN
                RAISE EXCEPTION 'fn_finalize_class_placements: specialite_code "%" is not a spécialité of filière "%" (draft "%")', v_specialite_code, v_filiere_code, v_class_record ->> 'name'
                  USING ERRCODE = '23503';
            END IF;
        END IF;

        -- The unique constraint is (tenant_id, academic_year_id, code).
        SELECT TRUE INTO v_class_found
          FROM public.classes c
         WHERE c.tenant_id = v_tenant
           AND c.academic_year_id = v_target_year.id
           AND c.code = v_code;
        IF v_class_found THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: class code "%" already exists in year %', v_code, v_target_year.label
              USING ERRCODE = '23505';
        END IF;

        INSERT INTO public.classes (
            tenant_id, academic_year_id, academic_level_id,
            code, name, grade_code, section,
            room, capacity,
            homeroom_teacher_id, homeroom_teacher_name,
            filiere_code, specialite_code,
            is_active
        ) VALUES (
            v_tenant, v_target_year.id, v_academic_level_id,
            v_code, v_class_record ->> 'name', v_class_record ->> 'gradeCode',
            COALESCE(NULLIF(v_class_record ->> 'section', ''), 'A'),
            NULLIF(v_class_record ->> 'room', ''),
            COALESCE(NULLIF(v_class_record ->> 'capacity', '')::int, 30),
            CASE
                WHEN NULLIF(v_class_record ->> 'homeroomTeacherId', '') IS NULL THEN NULL
                ELSE (v_class_record ->> 'homeroomTeacherId')::uuid
            END,
            NULLIF(v_class_record ->> 'homeroomTeacherName', ''),
            CASE WHEN v_filiere_code = 'general' THEN NULL ELSE v_filiere_code END,
            v_specialite_code,
            TRUE
        )
        RETURNING id INTO v_created_class_id;

        IF v_draft_id IS NOT NULL THEN
            v_created_classes_map := jsonb_set(
                v_created_classes_map,
                ARRAY[v_draft_id],
                to_jsonb(v_created_class_id::text)
            );
        END IF;

        v_created_classes_count := v_created_classes_count + 1;
    END LOOP;

    -- ── Step B: apply patches to EXISTING classes of the target year ──────
    -- (room / capacity / homeroom only — classification is set at creation
    --  or via class editing, deliberately not patchable here: changing a
    --  class's stream mid-formation would strand already-assigned students.)
    FOR v_update_record IN SELECT * FROM jsonb_array_elements(p_updated_classes)
    LOOP
        IF (v_update_record ->> 'id')::uuid IS NULL THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: class update entry lacks a valid id (%)', v_update_record
              USING ERRCODE = '22023';
        END IF;

        UPDATE public.classes c
           SET room = CASE WHEN v_update_record ? 'room'
                           THEN NULLIF(v_update_record ->> 'room', '') ELSE c.room END,
               capacity = CASE WHEN v_update_record ? 'capacity'
                               THEN COALESCE(NULLIF(v_update_record ->> 'capacity', '')::int, c.capacity)
                               ELSE c.capacity END,
               homeroom_teacher_id = CASE
                   WHEN v_update_record ? 'homeroomTeacherId' THEN
                       CASE WHEN NULLIF(v_update_record ->> 'homeroomTeacherId', '') IS NULL THEN NULL
                            ELSE (v_update_record ->> 'homeroomTeacherId')::uuid END
                   ELSE c.homeroom_teacher_id END,
               homeroom_teacher_name = CASE WHEN v_update_record ? 'homeroomTeacherName'
                                             THEN NULLIF(v_update_record ->> 'homeroomTeacherName', '')
                                             ELSE c.homeroom_teacher_name END,
               updated_at = now()
         WHERE c.id = (v_update_record ->> 'id')::uuid
           AND c.tenant_id = v_tenant
           AND c.academic_year_id = v_target_year.id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: class % not found in tenant/year % (existing-class patches must target the placement year)', v_update_record ->> 'id', v_target_year.label
              USING ERRCODE = '23503';
        END IF;

        v_updated_classes_count := v_updated_classes_count + 1;
    END LOOP;

    -- ── Step C: assign students to their target sections ──────────────────
    -- Historical records are deliberately NOT touched (INV-1 of the studio
    -- spec): student_academic_histories rows belong to the promotion flow.
    FOR v_student_record IN SELECT * FROM jsonb_array_elements(p_student_assignments)
    LOOP
        -- Resolve the final target class id (draft map first, then UUID).
        IF v_student_record ->> 'targetClassId' IS NOT NULL
           AND v_created_classes_map ? (v_student_record ->> 'targetClassId') THEN
            v_final_target_class_id := (v_created_classes_map ->> (v_student_record ->> 'targetClassId'))::uuid;
        ELSIF NULLIF(v_student_record ->> 'targetClassId', '') IS NOT NULL THEN
            v_final_target_class_id := (v_student_record ->> 'targetClassId')::uuid;
        ELSE
            RAISE EXCEPTION 'fn_finalize_class_placements: assignment for student % lacks a targetClassId', v_student_record ->> 'studentId'
              USING ERRCODE = '22023';
        END IF;

        -- Target class must exist in the tenant (RLS hides foreign rows →
        -- not found → the batch fails closed).
        SELECT c.grade_code, c.filiere_code, c.specialite_code
          INTO v_target_class_grade, v_class_filiere, v_class_specialite
          FROM public.classes c
         WHERE c.id = v_final_target_class_id
           AND c.tenant_id = v_tenant;
        IF v_target_class_grade IS NULL THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: target class % not found in tenant %', v_final_target_class_id, v_tenant
              USING ERRCODE = '23503';
        END IF;

        -- Grade integrity: the assignment's gradeLevel must match the
        -- target section's grade (prevents cross-grade corruption).
        IF NULLIF(v_student_record ->> 'gradeLevel', '') IS NOT NULL
           AND v_student_record ->> 'gradeLevel' <> v_target_class_grade THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: student % assignment grade "%" does not match target class grade "%"', v_student_record ->> 'studentId', v_student_record ->> 'gradeLevel', v_target_class_grade
              USING ERRCODE = '22023';
        END IF;

        -- Student must exist in the caller's tenant (not deleted); fetch
        -- the current classification for the compatibility check. FOUND
        -- distinguishes "row with NULL filière" from "no row".
        SELECT s.filiere_code, s.specialite_code
          INTO v_student_filiere, v_student_specialite
          FROM public.students s
         WHERE s.id = (v_student_record ->> 'studentId')::uuid
           AND s.tenant_id = v_tenant
           AND s.deleted_at IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: student % not found in tenant %', v_student_record ->> 'studentId', v_tenant
              USING ERRCODE = '23503';
        END IF;

        -- T-401: classification compatibility — a conflicting stream is a
        -- hard error (the whole batch rolls back, like the grade check).
        IF NOT public.fn_track_compatible(
                 v_student_filiere, v_student_specialite,
                 v_class_filiere, v_class_specialite,
                 v_target_class_grade, v_tenant) THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: student % classification (filière "%" / spécialité "%") is incompatible with target class % (filière "%" / spécialité "%")',
                v_student_record ->> 'studentId', coalesce(v_student_filiere, '—'), coalesce(v_student_specialite, '—'),
                v_final_target_class_id, coalesce(v_class_filiere, '—'), coalesce(v_class_specialite, '—')
              USING ERRCODE = '22023';
        END IF;

        UPDATE public.students
           SET class_id = v_final_target_class_id,
               grade_level_code = COALESCE(NULLIF(v_student_record ->> 'gradeLevel', ''), grade_level_code),
               -- T-401: a tagged class stamps the student's classification
               -- (the legitimate year-end re-streaming transition). An
               -- untagged class leaves the student's classification intact.
               filiere_code = CASE WHEN v_class_filiere IS NOT NULL THEN v_class_filiere
                                   ELSE filiere_code END,
               specialite_code = CASE WHEN v_class_specialite IS NOT NULL THEN v_class_specialite
                                       ELSE specialite_code END,
               updated_at = now()
         WHERE id = (v_student_record ->> 'studentId')::uuid
           AND tenant_id = v_tenant;

        v_assigned_students_count := v_assigned_students_count + 1;
    END LOOP;

    -- ── Step D: ONE audit entry for the whole batch (0014 entry point) ────
    PERFORM public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'class.placement_finalize',
        p_entity_type := 'class',
        p_entity_id   := NULL,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json  := jsonb_build_object(
                             'target_academic_year', v_target_year.label,
                             'classes_created', v_created_classes_count,
                             'classes_updated', v_updated_classes_count,
                             'students_assigned', v_assigned_students_count
                         ),
        p_note        := format('Constitution des classes effectuée pour %s : %s classe(s) créée(s), %s mise(s) à jour, %s élève(s) affecté(s).',
                                v_target_year.label, v_created_classes_count, v_updated_classes_count, v_assigned_students_count)
    );

    RETURN jsonb_build_object(
        'ok', TRUE,
        'targetYearId', v_target_year.id,
        'createdClassesCount', v_created_classes_count,
        'updatedClassesCount', v_updated_classes_count,
        'assignedStudentsCount', v_assigned_students_count
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_fnv1a(s text)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
declare
    h bigint := 2166136261;   -- 0x811C9DC5 (FNV-1a offset basis, unsigned)
    c integer;
    x bigint;
begin
    if s is null then s := ''; end if;
    for i in 1 .. length(s) loop
        c := ascii(substring(s from i for 1));
        -- XOR needs both operands in signed int range: normalize h.
        x := h;
        if x >= 2147483648 then x := x - 4294967296; end if;
        x := (x # c)::bigint;
        if x < 0 then x := x + 4294967296; end if;
        -- JS Math.imul truncates to 32 bits == mod 2^32 (bigint-safe).
        h := (x * 16777619) % 4294967296;
    end loop;
    return h;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_freeze_re_enrollments(p_target_academic_year_id uuid, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_reenrollment_tenant(p_tenant_id);
    v_target public.academic_years;
    v_total integer := 0;
    v_waiting integer := 0;
    v_frozen integer := 0;
begin
    select * into v_target from public.academic_years ay
     where ay.id = p_target_academic_year_id and ay.tenant_id = v_tenant;
    if v_target.id is null then
        raise exception 'fn_freeze_re_enrollments: année cible introuvable dans le tenant'
          using errcode = '23503';
    end if;

    select count(*),
           count(*) filter (where re.status = 'waiting'),
           count(*) filter (where re.frozen_at is not null)
      into v_total, v_waiting, v_frozen
      from public.re_enrollments re
     where re.tenant_id = v_tenant
       and re.target_academic_year_id = p_target_academic_year_id;

    if v_total = 0 then
        raise exception 'fn_freeze_re_enrollments: aucun candidat généré pour % — générez la liste d''abord', v_target.code
          using errcode = '55006';
    end if;

    if v_frozen > 0 then
        raise exception 'fn_freeze_re_enrollments: la liste % est DÉJÀ figée', v_target.code
          using errcode = '55006';
    end if;

    -- INV-23b: the freeze REFUSES while any candidate is still waiting —
    -- "record that decision rather than leaving them unresolved".
    if v_waiting > 0 then
        raise exception 'fn_freeze_re_enrollments: % candidat(s) en attente de décision pour % — décidez chaque élève avant de figer', v_waiting, v_target.code
          using errcode = '55006';
    end if;

    update public.re_enrollments re
       set frozen_at = now(),
           updated_at = now()
     where re.tenant_id = v_tenant
       and re.target_academic_year_id = p_target_academic_year_id
       and re.frozen_at is null;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 're_enrollment.frozen',
        p_entity_type := 're_enrollment',
        p_entity_id   := null,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json  := jsonb_build_object(
                             'target_academic_year', v_target.code,
                             'total', v_total
                         ),
        p_note        := format('Liste de réinscription %s FIGÉE (%s candidat(s)) — la revue est terminée.', v_target.code, v_total)
    );

    return jsonb_build_object(
        'ok', true,
        'target_academic_year', v_target.code,
        'frozen_count', v_total
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_reopen_promotion_cycle_class(p_cycle_id uuid, p_class_id uuid, p_reason text DEFAULT NULL::text, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_cycle_tenant(p_tenant_id);
    v_cycle public.promotion_cycles;
    v_class_row public.promotion_cycle_classes;
    v_awaiting integer;
begin
    select * into v_cycle
      from public.promotion_cycles pc
     where pc.id = p_cycle_id and pc.tenant_id = v_tenant
     for update;
    if v_cycle.id is null then
        raise exception 'fn_reopen_promotion_cycle_class: cycle % not found in tenant', p_cycle_id
          using errcode = '23503';
    end if;
    if v_cycle.status in ('completed', 'cancelled') then
        raise exception 'fn_reopen_promotion_cycle_class: the cycle for % is % — its classes can no longer be reopened', v_cycle.source_academic_year, v_cycle.status
          using errcode = '55006';
    end if;

    select * into v_class_row
      from public.promotion_cycle_classes pcc
     where pcc.cycle_id = p_cycle_id and pcc.class_id = p_class_id and pcc.tenant_id = v_tenant
     for update;
    if v_class_row.id is null then
        raise exception 'fn_reopen_promotion_cycle_class: class % is not part of cycle %', p_class_id, p_cycle_id
          using errcode = '23503';
    end if;
    if v_class_row.status not in ('processed', 'exception', 'skipped') then
        raise exception 'fn_reopen_promotion_cycle_class: the class % is % — nothing to reopen', v_class_row.class_name, v_class_row.status
          using errcode = '55006';
    end if;

    -- The live awaiting count for a reopened review.
    select count(*) into v_awaiting
      from public.students s
     where s.class_id = p_class_id
       and s.tenant_id = v_tenant
       and s.deleted_at is null
       and s.is_active;

    update public.promotion_cycle_classes pcc
       set status = 'in_review',
           students_awaiting = v_awaiting,
           exception_note = null,
           updated_at = now()
     where pcc.id = v_class_row.id;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'promotion.cycle_class_reopen',
        p_entity_type := 'promotion_cycle',
        p_entity_id   := p_cycle_id,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json   := jsonb_build_object('class', v_class_row.class_name, 'reason', p_reason),
        p_note         := format('Classe %s rouverte dans le cycle %s → %s.', v_class_row.class_name, v_cycle.source_academic_year, v_cycle.target_academic_year)
    );

    return jsonb_build_object('ok', true, 'class_name', v_class_row.class_name, 'status', 'in_review');
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_resolve_cycle_tenant(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_tenant uuid;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    v_tenant := public.current_tenant_id();
    if p_tenant_id is not null and (v_tenant is null or p_tenant_id <> v_tenant) then
        if not v_caller_is_service_role and not public.is_global_admin() then
            raise exception 'promotion cycle: caller tenant mismatch (p_tenant_id=%)', p_tenant_id
              using errcode = '42501';
        end if;
        v_tenant := p_tenant_id;
    end if;
    if v_tenant is null then
        raise exception 'promotion cycle: caller tenant unresolvable'
          using errcode = '42501';
    end if;
    return v_tenant;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_resolve_reenrollment_tenant(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_tenant uuid;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    v_tenant := public.current_tenant_id();
    if p_tenant_id is not null and (v_tenant is null or p_tenant_id <> v_tenant) then
