CREATE OR REPLACE FUNCTION public.register_fcm_token(p_user_id uuid, p_token text, p_platform text DEFAULT 'android'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_token_id uuid;
    v_tenant_id uuid;
    v_caller_profile uuid;
    v_is_service_role boolean;
    v_conflict_user uuid;
    v_conflict_active boolean;
    v_id uuid;
BEGIN
    IF p_token IS NULL OR trim(p_token) = '' THEN
        RAISE EXCEPTION 'p_token is required';
    END IF;

    -- SEC-106 (0050): verify the caller owns the profile they register for.
    v_is_service_role := (auth.role() = 'service_role');
    IF NOT v_is_service_role THEN
        SELECT up.id INTO v_caller_profile
          FROM public.user_profiles up
         WHERE up.auth_user_id = auth.uid()
         LIMIT 1;
        IF v_caller_profile IS NULL OR v_caller_profile <> p_user_id THEN
            RAISE EXCEPTION 'register_fcm_token: caller does not own user profile %', p_user_id
              USING ERRCODE = '42501';
        END IF;
    END IF;

    -- Resolve tenant from the user's profile.
    SELECT tenant_id INTO v_tenant_id
      FROM public.user_profiles
     WHERE id = p_user_id
     LIMIT 1;

    IF v_tenant_id IS NULL THEN
        -- Default tenant — matches the seed in 0023.
        v_tenant_id := '00000000-0000-0000-0000-000000000001'::uuid;
    END IF;

    -- T-030: inspect the conflicting row BEFORE the upsert so the silent
    -- re-point can be distinguished from a legitimate reactivation.
    SELECT dt.user_id, dt.is_active
      INTO v_conflict_user, v_conflict_active
      FROM public.device_tokens dt
     WHERE dt.tenant_id = v_tenant_id
       AND dt.token = p_token
     LIMIT 1;

    IF v_conflict_user IS NOT NULL AND v_conflict_user <> p_user_id THEN
        IF v_conflict_active THEN
            -- PUSH-102: the token belongs to an ACTIVE session of another
            -- user — a silent transfer would hijack their notifications.
            -- The canonical sign-out (deactivate_fcm_tokens) is the
            -- legitimate way to release the device first.
            RAISE EXCEPTION 'register_fcm_token: token is registered to an ACTIVE device of user % — transfer requires that user to sign out first', v_conflict_user
              USING ERRCODE = '42501';
        END IF;
        -- Inactive conflict = the previous owner signed out: explicit
        -- transfer, AUDITED (PUSH-102 "audit + explicit transfer").
        INSERT INTO public.device_tokens (tenant_id, user_id, token, platform, is_active, last_seen_at)
        VALUES (v_tenant_id, p_user_id, p_token, p_platform, true, now())
        ON CONFLICT (tenant_id, token) DO UPDATE
           SET user_id       = EXCLUDED.user_id,
               platform      = EXCLUDED.platform,
               is_active     = true,
               last_seen_at  = now()
        RETURNING id INTO v_token_id;

        PERFORM public.write_audit_log(
            p_tenant_id   := v_tenant_id,
            p_action      := 'device_token.transfer',
            p_entity_type := 'device_token',
            p_entity_id   := v_token_id,
            p_actor_id    := p_user_id,
            p_before_json := jsonb_build_object('user_id', v_conflict_user, 'is_active', false),
            p_after_json  := jsonb_build_object('user_id', p_user_id, 'is_active', true),
            p_note        := 'Transfert de jeton FCM (appareil partagé, ancien propriétaire déconnecté)'
        );
        RETURN v_token_id;
    END IF;

    -- Same user (or brand-new row): plain reactivation/registration.
    INSERT INTO public.device_tokens (tenant_id, user_id, token, platform, is_active, last_seen_at)
    VALUES (v_tenant_id, p_user_id, p_token, p_platform, true, now())
    ON CONFLICT (tenant_id, token) DO UPDATE
       SET user_id       = EXCLUDED.user_id,
           platform      = EXCLUDED.platform,
           is_active     = true,
           last_seen_at  = now()
    RETURNING id INTO v_token_id;

    PERFORM public.write_audit_log(
        p_tenant_id   := v_tenant_id,
        p_action      := 'device_token.register',
        p_entity_type := 'device_token',
        p_entity_id   := v_token_id,
        p_actor_id    := p_user_id,
        p_after_json  := jsonb_build_object('platform', p_platform, 'active', true),
        p_note        := 'Enregistrement (ré)activé de jeton FCM'
    );

    RETURN v_token_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_installment_ref(p_tenant_id uuid, p_installment_ref text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uuid uuid;
    v_id   uuid;
BEGIN
    IF p_installment_ref IS NULL OR TRIM(p_installment_ref) = '' THEN
        RETURN NULL;
    END IF;

    BEGIN
        v_uuid := p_installment_ref::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        v_uuid := NULL;
    END;
    IF v_uuid IS NOT NULL THEN
        RETURN v_uuid;
    END IF;

    -- Mobile local ref → android_sync provenance row.
    SELECT id INTO v_id FROM public.installments
     WHERE tenant_id = p_tenant_id
       AND source_type = 'android_sync'
       AND source_id = p_installment_ref
     LIMIT 1;
    RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_parent_ref(p_tenant_id uuid, p_parent_ref text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uuid uuid;
    v_id   uuid;
BEGIN
    IF p_parent_ref IS NULL OR TRIM(p_parent_ref) = '' THEN
        RETURN NULL;
    END IF;

    -- 1a. Already a server UUID (desktop push / pull round-trip).
    BEGIN
        v_uuid := p_parent_ref::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        v_uuid := NULL;
    END;
    IF v_uuid IS NOT NULL THEN
        SELECT id INTO v_id FROM public.parents
         WHERE id = v_uuid AND tenant_id = p_tenant_id AND deleted_at IS NULL;
        RETURN COALESCE(v_id, v_uuid);  -- trust valid UUIDs even if not yet present
    END IF;

    -- 1b. Android local ref → canonical parent_code ("PAR-YYYY-XXXXXX").
    SELECT id INTO v_id FROM public.parents
     WHERE tenant_id = p_tenant_id AND parent_code = p_parent_ref AND deleted_at IS NULL
     LIMIT 1;
    RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_student_ref(p_tenant_id uuid, p_student_ref text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uuid uuid;
    v_id   uuid;
BEGIN
    IF p_student_ref IS NULL OR TRIM(p_student_ref) = '' THEN
        RETURN NULL;
    END IF;

    BEGIN
        v_uuid := p_student_ref::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        v_uuid := NULL;
    END;
    IF v_uuid IS NOT NULL THEN
        SELECT id INTO v_id FROM public.students
         WHERE id = v_uuid AND tenant_id = p_tenant_id AND deleted_at IS NULL;
        RETURN COALESCE(v_id, v_uuid);
    END IF;

    SELECT id INTO v_id FROM public.students
     WHERE tenant_id = p_tenant_id AND student_code = p_student_ref AND deleted_at IS NULL
     LIMIT 1;
    RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.respond_leave_clarification(p_request_id uuid, p_response text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_profile_id uuid;
  v_tenant_id uuid;
  v_status text;
begin
  v_profile_id := public.current_user_profile_id();
  v_tenant_id := public.current_tenant_id();

  if v_profile_id is null or v_tenant_id is null then
    raise exception 'Authentication context is required';
  end if;

  if btrim(coalesce(p_response, '')) = '' then
    raise exception 'A clarification response is required';
  end if;

  select lr.status
    into v_status
  from public.leave_requests lr
  join public.personnel p
    on p.id = lr.personnel_id
   and p.tenant_id = lr.tenant_id
  where lr.id = p_request_id
    and lr.tenant_id = v_tenant_id
    and p.user_id = v_profile_id
    and p.deleted_at is null
  for update;

  if not found then
    raise exception 'Leave request not found or not owned by the current user';
  end if;

  if v_status <> 'clarification_requested' then
    raise exception 'Leave request is not awaiting clarification response';
  end if;

  update public.leave_requests
  set
    status = 'pending',
    clarification_response = btrim(p_response),
    updated_at = now()
  where id = p_request_id
    and tenant_id = v_tenant_id;

  return p_request_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.revert_payment_allocation(p_tenant_id uuid, p_payment_id uuid, p_actor_id uuid, p_actor_name text, p_reason text, p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(payment_id uuid, new_status text, reversal_entry_id text, reverts_count integer, total_reverted numeric)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_payment RECORD;
  v_original_ledger RECORD;
  v_reversal_id TEXT;
  v_reverts JSONB := '[]'::JSONB;
  v_count INT := 0;
  v_total_reverted NUMERIC := 0;
  v_remaining NUMERIC;
  v_ins RECORD;
  v_revert NUMERIC;
  v_new_paid NUMERIC;
  v_new_pending NUMERIC;
  v_new_status TEXT;
  v_original_was_pending BOOLEAN;
  -- T-310: resolved actor (see collect_and_allocate_payment).
  v_actor_name TEXT; v_actor_role TEXT;
BEGIN
  -- T-310 (AUDIT-502): resolve the actor ONCE (same rules as collect).
  IF p_actor_name IS NOT NULL AND p_actor_name <> '' AND p_actor_name <> p_actor_id::TEXT THEN
    v_actor_name := p_actor_name;
  ELSE
    SELECT coalesce(up.display_name, up.email) INTO v_actor_name
      FROM public.user_profiles up
     WHERE up.id = p_actor_id OR up.auth_user_id = p_actor_id
     ORDER BY (up.id = p_actor_id) DESC
     LIMIT 1;
    v_actor_name := coalesce(v_actor_name, 'System');
  END IF;
  SELECT r.code INTO v_actor_role
    FROM public.role_assignments ra
    JOIN public.roles r ON r.id = ra.role_id
   WHERE ra.user_profile_id = (
         SELECT up.id FROM public.user_profiles up
          WHERE up.id = p_actor_id OR up.auth_user_id = p_actor_id
          ORDER BY (up.id = p_actor_id) DESC LIMIT 1)
     AND ra.revoked_at IS NULL
   ORDER BY r.code
   LIMIT 1;

  -- 1. Lock payment row.
  -- SEC-112: the lookup is now tenant-scoped — a payment from another
  -- tenant is indistinguishable from a nonexistent one ("not found"),
  -- so cross-tenant refunds are impossible even for service_role
  -- callers (which bypass RLS). INVOKER callers were already protected
  -- by the payments RLS SELECT policy; this closes the DEFINER/svc gap.
  SELECT * INTO v_payment FROM payments WHERE id = p_payment_id AND tenant_id = p_tenant_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment % not found', p_payment_id;
  END IF;
  IF v_payment.status NOT IN ('paid', 'pending') THEN
    RAISE EXCEPTION 'Payment % is already % (cannot revert)', p_payment_id, v_payment.status;
  END IF;

  -- 2. Update payment status.
  UPDATE payments SET status = 'refunded', updated_at = p_as_of WHERE id = p_payment_id;

  -- 3. Find original ledger entry + insert reversal.
  SELECT * INTO v_original_ledger
    FROM ledger_entries
    WHERE source_type = 'payment' AND source_id = p_payment_id::TEXT AND entry_type = 'payment'
    LIMIT 1;

  IF FOUND THEN
    -- Determine originalWasPending: true if the original payment's status
    -- was 'pending' (uncleared funds). This is the CRITICAL branch.
    v_original_was_pending := (v_original_ledger.payment_status = 'pending');

    -- FRESH-DB FIX: same triple bug (type column, text id into uuid PK,
    -- missing NOT NULL entry_number).
    v_reversal_id := 'led-' || EXTRACT(EPOCH FROM NOW()) || '-' || SUBSTRING(gen_random_uuid()::TEXT, 1, 8);
    INSERT INTO ledger_entries (
      entry_number, tenant_id, account_id, parent_id, student_id, category, amount,
      entry_type, source_type, source_id, method, receipt_number, payment_status,
      reverses_id, description, actor_id, actor_name, at, metadata
    ) VALUES (
      v_reversal_id, v_payment.tenant_id, v_original_ledger.account_id,
      v_original_ledger.parent_id, v_original_ledger.student_id,
      v_original_ledger.category, -v_original_ledger.amount,
      'reversal', 'payment', p_payment_id::TEXT,
      -- Canonical: refund/reversal entries have method=null, paymentStatus=null.
      NULL, v_original_ledger.receipt_number, NULL,
      v_original_ledger.id::TEXT,
      'Remboursement ' || v_payment.receipt_number || ' — inversion de l''écriture de paiement',
      p_actor_id::TEXT, v_actor_name, p_as_of,
      JSONB_BUILD_OBJECT('refundReason', p_reason, 'originalPaymentId', p_payment_id, 'originalWasPending', v_original_was_pending)
    );

    -- 4. LIFO reverse-waterfall.
    v_remaining := v_payment.amount;

    IF v_original_was_pending THEN
      -- Pending branch: subtract from amount_pending. NEVER touch amount_paid.
      FOR v_ins IN
        SELECT id, amount_due, amount_paid, amount_pending, due_date, status
        FROM installments
        WHERE parent_id = v_payment.parent_id
          AND amount_pending > 0
          AND (v_payment.category IS NULL OR category = v_payment.category)
        ORDER BY due_date DESC, id DESC
        FOR UPDATE
      LOOP
        EXIT WHEN v_remaining <= 0;
        v_revert := LEAST(v_remaining, v_ins.amount_pending);
        v_new_pending := v_ins.amount_pending - v_revert;
        v_new_paid := v_ins.amount_paid;  -- UNCHANGED for pending reversals
        -- Status re-evaluation: pending reversal doesn't change paid amount,
        -- so if there were no cleared funds, tranche reverts to its prior
        -- non-pending status based on amount_paid vs amount_due.
        IF v_new_paid >= v_ins.amount_due AND v_ins.amount_due > 0 THEN
          v_new_status := 'paid';
        ELSIF v_new_paid > 0 THEN
          v_new_status := 'partial';
        ELSIF v_ins.due_date < p_as_of THEN
          v_new_status := 'overdue';
        ELSE
          -- Canonical reevaluateInstallmentStatus: fully unpaid + future due
          -- date reverts to 'pending' (equivalence finding A-0042-LADDER).
          v_new_status := 'pending';
        END IF;
        -- If amount_pending is now 0, status reverts to the above. If > 0,
        -- keep pending_clearance (still has uncleared funds).
        IF v_new_pending > 0 THEN
          v_new_status := 'pending_clearance';
        END IF;
        UPDATE installments
          SET amount_paid = v_new_paid, amount_pending = v_new_pending,
              status = v_new_status,
              paid_date = CASE WHEN v_new_status = 'paid' THEN paid_date ELSE NULL END
          WHERE id = v_ins.id;
        v_reverts := v_reverts || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
          'installmentId', v_ins.id, 'revertedAmount', v_revert,
          'newAmountPaid', v_new_paid, 'newAmountPending', v_new_pending,
          'newStatus', v_new_status, 'bucket', 'pending'
        ));
        v_count := v_count + 1;
        v_total_reverted := v_total_reverted + v_revert;
        v_remaining := v_remaining - v_revert;
      END LOOP;
    ELSE
      -- Cleared branch: subtract from amount_paid.
      FOR v_ins IN
        SELECT id, amount_due, amount_paid, amount_pending, due_date, status
        FROM installments
        WHERE parent_id = v_payment.parent_id
          AND amount_paid > 0
          AND (v_payment.category IS NULL OR category = v_payment.category)
        ORDER BY due_date DESC, id DESC
        FOR UPDATE
      LOOP
        EXIT WHEN v_remaining <= 0;
        v_revert := LEAST(v_remaining, v_ins.amount_paid);
        v_new_paid := v_ins.amount_paid - v_revert;
        v_new_pending := v_ins.amount_pending;  -- unchanged for cleared reversals
        IF v_new_paid >= v_ins.amount_due AND v_ins.amount_due > 0 THEN
          v_new_status := 'paid';
        ELSIF v_new_paid > 0 THEN
          v_new_status := 'partial';
        ELSIF v_ins.due_date < p_as_of THEN
          v_new_status := 'overdue';
        ELSE
          -- Canonical reevaluateInstallmentStatus: fully unpaid + future due
          -- date reverts to 'pending' (equivalence finding A-0042-LADDER).
          v_new_status := 'pending';
        END IF;
        UPDATE installments
          SET amount_paid = v_new_paid, amount_pending = v_new_pending,
              status = v_new_status,
              paid_date = CASE WHEN v_new_status = 'paid' THEN paid_date ELSE NULL END
          WHERE id = v_ins.id;
        v_reverts := v_reverts || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
          'installmentId', v_ins.id, 'revertedAmount', v_revert,
          'newAmountPaid', v_new_paid, 'newAmountPending', v_new_pending,
          'newStatus', v_new_status, 'bucket', 'paid'
        ));
        v_count := v_count + 1;
        v_total_reverted := v_total_reverted + v_revert;
        v_remaining := v_remaining - v_revert;
      END LOOP;
    END IF;
  END IF;

  -- 5. Audit log.
  -- SEC-112: stamped with the PAYMENT's actual tenant (v_payment.tenant_id),
  -- no longer the caller-supplied p_tenant_id.
  -- T-310 (AUDIT-502): the wrapped {before, after} payload now ALSO lands in
  -- the canonical columns (unwrapped) + actor_role; the legacy `diff` column
  -- keeps the wrapped shape for backward compat.
  INSERT INTO audit_logs (
    id, tenant_id, action, entity_type, entity_id, actor_id, actor_name, actor_role,
    before_json, after_json, diff, note, created_at
  ) VALUES (
    gen_random_uuid(), v_payment.tenant_id, 'payment.refund', 'payment', p_payment_id,
    p_actor_id, v_actor_name, v_actor_role,
    JSONB_BUILD_OBJECT('status', v_payment.status),
    JSONB_BUILD_OBJECT(
      'status', 'refunded', 'reversalEntryId', v_reversal_id,
      'revertsCount', v_count, 'totalReverted', v_total_reverted,
      'originalWasPending', v_original_was_pending
    ),
    JSONB_BUILD_OBJECT(
      'before', JSONB_BUILD_OBJECT('status', v_payment.status),
      'after', JSONB_BUILD_OBJECT(
        'status', 'refunded', 'reversalEntryId', v_reversal_id,
        'revertsCount', v_count, 'totalReverted', v_total_reverted,
        'originalWasPending', v_original_was_pending
      )
    ),
    'Inversion LIFO via RPC revert_payment_allocation (canonical 0034) — ' || COALESCE(p_reason, 'N/A'),
    p_as_of
  );

  RETURN QUERY
    SELECT p_payment_id, 'refunded'::TEXT, v_reversal_id, v_count, v_total_reverted;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_dashboard_layout(p_view_key text, p_layout jsonb)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
    v_profile uuid;
    v_tenant  uuid;
    v_saved_at timestamptz;
begin
    -- Identity resolved SERVER-SIDE from the JWT: the caller cannot target
    -- another user's row (the client never sends tenant/profile columns).
    v_profile := public.current_user_profile_id();
    v_tenant  := public.current_tenant_id();
    if v_profile is null or v_tenant is null then
        raise exception 'save_dashboard_layout: no profile/tenant context'
          using errcode = '42501';
    end if;

    if p_view_key is null or btrim(p_view_key) = '' then
        raise exception 'save_dashboard_layout: p_view_key is required'
          using errcode = '23514';
    end if;
    if p_layout is null or jsonb_typeof(p_layout) <> 'object' then
        raise exception 'save_dashboard_layout: p_layout must be a JSON object'
          using errcode = '23514';
    end if;

    insert into public.dashboard_layouts (tenant_id, user_profile_id, view_key, layout)
    values (v_tenant, v_profile, btrim(p_view_key), p_layout)
    on conflict (tenant_id, user_profile_id, view_key)
    do update set layout = excluded.layout
    returning updated_at into v_saved_at;

    return v_saved_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_active_pricing_config(p_config_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant uuid;
    v_target public.pricing_configs%rowtype;
begin
    -- Gate 1 — staff roles (mirrors the 0019 pricing_configs_admin policy:
    -- pricing writes are super_admin / financial_officer).
    if not public.has_any_role(array['super_admin', 'financial_officer']) then
        raise exception 'forbidden: pricing activation is a staff surface'
            using errcode = '42501';
    end if;

    -- Gate 2 — tenant scope (SECURITY DEFINER bypasses the RLS that would
    -- normally scope writes; current_tenant_id() is the canonical resolver).
    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        raise exception 'forbidden: no tenant context'
            using errcode = '42501';
    end if;

    select * into v_target
      from public.pricing_configs
     where id = p_config_id;

    if v_target.id is null then
        raise exception 'pricing config not found: %', p_config_id
            using errcode = '22023';
    end if;

    if v_target.tenant_id <> v_tenant then
        raise exception 'forbidden: pricing config belongs to another tenant'
            using errcode = '42501';
    end if;

    if v_target.is_active then
        -- Idempotent no-op: activating the already-active config.
        return v_target.id;
    end if;

    -- The switch, atomically: deactivate siblings, activate the target.
    update public.pricing_configs
       set is_active = false,
           updated_at = now()
     where tenant_id = v_tenant
       and is_active
       and id <> p_config_id;

    update public.pricing_configs
       set is_active = true,
           updated_at = now()
     where id = p_config_id
    returning * into v_target;

    -- 0086 pricing mutation triggers already audit both UPDATEs (before/after
    -- snapshots with actor attribution) — no manual audit row here.
    return v_target.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_current_academic_year(p_academic_year_id uuid, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS academic_years
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_year public.academic_years;
    v_tenant uuid;
    v_caller_is_service_role boolean;
    v_prev_year public.academic_years;
BEGIN
    v_caller_is_service_role := coalesce(auth.jwt() ->> 'role', '') = 'service_role';

    -- Tenant resolution (0055 pattern): explicit tenant allowed for
    -- service_role + global admins only; everyone else must BE of the tenant.
    v_tenant := public.current_tenant_id();
    IF p_tenant_id IS NOT NULL AND (v_tenant IS NULL OR p_tenant_id <> v_tenant) THEN
        IF NOT v_caller_is_service_role AND NOT public.is_global_admin() THEN
            RAISE EXCEPTION 'set_current_academic_year: caller tenant mismatch (p_tenant_id=%)', p_tenant_id
              USING ERRCODE = '42501';
        END IF;
        v_tenant := p_tenant_id;
    END IF;

    IF v_tenant IS NULL THEN
        RAISE EXCEPTION 'set_current_academic_year: caller tenant unresolvable'
          USING ERRCODE = '42501';
    END IF;

    -- Remember the tenant's previous current year for the audit diff.
    SELECT * INTO v_prev_year
      FROM public.academic_years ay
     WHERE ay.tenant_id = v_tenant AND ay.is_current
     LIMIT 1;

    -- ACAD-101: ONE statement — there is no zero-current-year window.
    UPDATE public.academic_years ay
       SET is_current = (ay.id = p_academic_year_id),
           updated_at = now()
     WHERE ay.tenant_id = v_tenant
     RETURNING ay.* INTO v_year;

    IF v_year.id IS NULL OR v_year.id <> p_academic_year_id THEN
        -- Either the target does not exist, is in another tenant (RLS hid
        -- it), or the caller lacks the academic_years_admin policy — the
        -- UPDATE matched zero rows or could not set the target. Roll back.
        RAISE EXCEPTION 'set_current_academic_year: academic year % not applicable for this caller', p_academic_year_id
          USING ERRCODE = '23503';
    END IF;

    PERFORM public.write_audit_log(
        p_tenant_id      := v_tenant,
        p_action         := 'academic_year.set_current',
        p_entity_type    := 'academic_year',
        p_entity_id      := p_academic_year_id,
        p_actor_id       := p_actor_profile_id,
        p_actor_name     := p_actor_name,
        p_before_json    := CASE WHEN v_prev_year.id IS NULL THEN NULL
                                 ELSE jsonb_build_object('id', v_prev_year.id, 'label', v_prev_year.label) END,
        p_after_json     := jsonb_build_object('id', v_year.id, 'label', v_year.label),
        p_note           := 'Année courante basculée (atomique, RPC 0059)'
    );

    RETURN v_year;
END;
$function$

