CREATE OR REPLACE FUNCTION public.settle_expense(p_tenant_id uuid, p_ticket_id uuid, p_final_amount numeric, p_receipt_path text, p_actor_profile_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_ticket record;
    v_audit_id uuid;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    -- ── Caller verification + actor binding (SEC-118, the 0055 pattern) ──
    if not v_caller_is_service_role then
        if auth.uid() is null then
            raise exception 'settle_expense: an authenticated caller is required';
        end if;
        if not public.has_any_role(array['super_admin', 'financial_officer', 'manager']) then
            raise exception 'settle_expense: only super_admin / financial_officer / manager may settle expenses';
        end if;
        if p_actor_profile_id is distinct from public.current_user_profile_id() then
            raise exception 'settle_expense: p_actor_profile_id must be the caller''s own profile (SEC-118 actor binding)';
        end if;
    end if;

    select * into v_ticket from public.expense_tickets where id = p_ticket_id and tenant_id = p_tenant_id;
    if not found then raise exception 'Expense ticket not found'; end if;

    if v_ticket.status not in ('approved_funds_released', 'disbursed') then
        raise exception 'Ticket must be approved_funds_released or disbursed to settle (current: %)', v_ticket.status;
    end if;

    if p_receipt_path is null or trim(p_receipt_path) = '' then
        raise exception 'Receipt upload is mandatory before settlement (plan §08)';
    end if;

    update public.expense_tickets
       set status = 'settled_and_closed',
           final_spent_amount = p_final_amount,
           receipt_path = p_receipt_path,
           receipt_uploaded_at = now(),
           receipt_uploaded_by = p_actor_profile_id,
           settled_by = p_actor_profile_id,
           settled_at = now(),
           updated_at = now()
     where id = p_ticket_id;

    v_audit_id := public.write_audit_log(
        p_tenant_id := p_tenant_id,
        p_action := 'expense.settle',
        p_entity_type := 'expense_ticket',
        p_entity_id := p_ticket_id,
        p_actor_id := p_actor_profile_id,
        p_after_json := jsonb_build_object('final_amount', p_final_amount, 'receipt_path', p_receipt_path)
    );

    return v_audit_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.soft_delete_parent(p_parent_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_row        public.parents%rowtype;
    v_active_kids integer;
begin
    -- Gate 1 — super_admin (the parents_delete RLS mirror).
    if not public.has_role('super_admin') then
        return jsonb_build_object('ok', false, 'code', 'forbidden');
    end if;

    -- Resolve + Gate 2 — tenant scope (404 semantics for unknown/cross-tenant).
    select p.* into v_row
      from public.parents p
     where p.id = p_parent_id
       and p.deleted_at is null
       and p.tenant_id = public.current_tenant_id();
    if not found then
        return jsonb_build_object('ok', false, 'code', 'not_found');
    end if;

    -- Gate 3 — the active-students guard (PARENT-500's core rule, canonical).
    select count(*) into v_active_kids
      from public.students s
     where s.parent_id = p_parent_id
       and s.tenant_id = v_row.tenant_id
       and s.deleted_at is null;
    if v_active_kids > 0 then
        return jsonb_build_object('ok', false, 'code', 'active_students_exist',
                                   'count', v_active_kids);
    end if;

    -- Gate 4 — the soft-delete itself, re-checking deleted_at (race-safe).
    update public.parents
       set deleted_at = now(),
           is_active  = false
     where id = p_parent_id
       and deleted_at is null;
    if not found then
        return jsonb_build_object('ok', false, 'code', 'not_found');
    end if;

    -- The intent record (the 0086 trigger adds the mechanism entry).
    perform public.write_audit_log(
        p_tenant_id   := v_row.tenant_id,
        p_action      := 'parent.delete',
        p_entity_type := 'parent',
        p_entity_id   := v_row.id,
        p_actor_id    := public.current_user_profile_id(),
        p_before_json := to_jsonb(v_row) - 'updated_at',
        p_after_json  := null,
        p_note        := 'Suppression logique (T-384 / soft_delete_parent) — l''historique financier est conservé'
    );

    return jsonb_build_object('ok', true, 'deleted_at', now());
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_apply_batch(p_mutations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '60s'
AS $function$
declare
    v_tenant uuid := public.current_tenant_id();
    m jsonb;
    v_entity text;
    v_payload jsonb;
    v_results jsonb := '[]'::jsonb;
    v_ids text[] := array[]::text[];
    v_parent_code text;
    v_student_code text;
    v_homework_row record;
begin
    if v_tenant is null then
        raise exception 'forbidden: no tenant context';
    end if;
    if p_mutations is null or jsonb_typeof(p_mutations) <> 'array' then
        raise exception 'invalid mutations payload: expected a jsonb array';
    end if;

    for m in select * from jsonb_array_elements(p_mutations) loop
        v_entity := m->>'entity';
        v_payload := coalesce(m->'payload', '{}'::jsonb);

        -- SYNC-102 (the confused-deputy guard, server-side): every
        -- mutation's tenant must equal the session's tenant.
        if (m->>'tenant_id')::text is not null and (m->>'tenant_id')::text <> v_tenant::text then
            raise exception 'forbidden: mutation % targets tenant % (session %)', m->>'id', m->>'tenant_id', v_tenant;
        end if;

        -- The audit row INSIDE the transaction (SYNC-101: ON CONFLICT DO
        -- NOTHING — a re-drain never resets the row to pending).
        insert into public.sync_queue (id, tenant_id, entity, operation, actor_id, payload, source_file, import_run_id, queued_at, status)
        values (
            m->>'id',
            v_tenant,
            v_entity,
            coalesce(m->>'operation', 'insert'),
            public.sync_safe_uuid(m->>'actor_id'),
            v_payload,
            m->>'source_file',
            m->>'import_run_id',
            coalesce((m->>'queued_at')::timestamptz, now()),
            'pending'
        )
        on conflict (id) do nothing;

        -- The canonical dispatch (ADR-002's authority unchanged — the
        -- per-mutation apply goes through the same upsert RPCs the
        -- per-item dispatcher uses).
        case v_entity
            when 'parent' then
                v_parent_code := coalesce(
                    public.sync_j(v_payload, 'code', 'parent_code'),
                    public.fn_deterministic_parent_code(
                        extract(year from now())::int,
                        public.sync_j(v_payload, 'phone', 'primary_phone'),
                        public.sync_j(v_payload, 'displayName', 'display_name'),
                        public.sync_j(v_payload, 'firstName', 'first_name'),
                        public.sync_j(v_payload, 'lastName', 'last_name'),
                        m->>'id'
                    )
                );
                perform public.upsert_parent_from_import(
                    v_tenant,
                    v_parent_code,
                    coalesce(public.sync_j(v_payload, 'firstName', 'first_name'), ''),
                    coalesce(public.sync_j(v_payload, 'lastName', 'last_name'), ''),
                    public.sync_j(v_payload, 'displayName', 'display_name'),
                    coalesce(public.sync_j(v_payload, 'phone', 'primary_phone'), '(inconnu)'),
                    public.sync_j(v_payload, 'whatsapp', 'secondary_phone'),
                    public.sync_j(v_payload, 'email', 'email'),
                    public.sync_j(v_payload, 'occupation', 'occupation'),
                    public.sync_j(v_payload, 'address', 'address'),
                    null,
                    coalesce(public.sync_j(v_payload, 'preferredLanguage', 'preferred_language'), 'fr'),
                    true,
                    public.sync_j(v_payload, 'transportDestination', 'transport_destination'),
                    public.sync_j(v_payload, 'cityTier', 'city_tier'),
                    public.fn_deterministic_activation_code(v_parent_code, v_tenant)
                );
            when 'student' then
                v_student_code := coalesce(
                    public.sync_j(v_payload, 'code', 'student_code'),
                    public.fn_deterministic_student_code(
                        extract(year from now())::int,
                        coalesce(public.sync_j(v_payload, 'parentId', 'parent_id'), ''),
                        public.sync_j(v_payload, 'displayName', 'display_name'),
                        public.sync_j(v_payload, 'firstName', 'first_name'),
                        public.sync_j(v_payload, 'lastName', 'last_name'),
                        m->>'id'
                    )
                );
                perform public.upsert_student_from_import(
                    v_tenant,
                    v_student_code,
                    coalesce(public.sync_j(v_payload, 'parentId', 'parent_id'), ''),
                    coalesce(public.sync_j(v_payload, 'firstName', 'first_name'), ''),
                    coalesce(public.sync_j(v_payload, 'lastName', 'last_name'), ''),
                    public.sync_j(v_payload, 'displayName', 'display_name'),
                    null,
                    nullif(btrim(coalesce(v_payload->>'birthDate', v_payload->>'date_of_birth', '')), '')::date,
                    case when v_payload->>'gender' = 'unspecified' then null else public.sync_j(v_payload, 'gender', 'gender') end,
                    null,
                    public.sync_safe_uuid(coalesce(v_payload->>'classId', v_payload->>'class_id')),
                    null,
                    'active',
                    public.sync_j(v_payload, 'medicalNotes', 'medical_notes'),
                    true,
                    public.sync_j(v_payload, 'gradeLevel', 'grade_level_code'),
                    public.sync_j(v_payload, 'transportTier', 'transport_tier'),
                    coalesce(public.sync_j(v_payload, 'paymentPlan', 'payment_plan'), 'tranches')
                );
            when 'payment' then
                perform public.upsert_payment_from_import(
                    v_tenant,
                    public.sync_j(v_payload, 'receiptNumber', 'payment_number'),
                    coalesce(public.sync_j(v_payload, 'parentId', 'parent_id'), ''),
                    public.sync_j(v_payload, 'studentId', 'student_id'),
                    null,
                    public.sync_j(v_payload, 'installmentId', 'installment_id'),
                    coalesce((coalesce(v_payload->>'amount', '0'))::numeric, 0),
                    coalesce(public.sync_j(v_payload, 'method', 'method'), 'cash'),
                    coalesce(public.sync_j(v_payload, 'category', 'category'), 'other'),
                    public.sync_j(v_payload, 'status', 'status'),
                    public.sync_j(v_payload, 'proofUrl', 'proof_path'),
                    nullif(btrim(coalesce(v_payload->>'collectedAt', v_payload->>'collected_at', '')), '')::timestamptz,
                    public.sync_safe_uuid(coalesce(v_payload->>'collectedBy', v_payload->>'collected_by')),
                    public.sync_j(v_payload, 'notes', 'notes')
                );
            when 'ledger_entry' then
                perform public.upsert_ledger_entry_from_import(
                    v_tenant,
                    coalesce(public.sync_j(v_payload, 'id', 'entry_number'), m->>'id'),
                    coalesce(public.sync_j(v_payload, 'parentId', 'parent_id'), ''),
                    public.sync_j(v_payload, 'studentId', 'student_id'),
                    public.sync_j(v_payload, 'accountId', 'account_id'),
                    coalesce(public.sync_j(v_payload, 'type', 'entry_type'), 'charge'),
                    coalesce((coalesce(v_payload->>'amount', '0'))::numeric, 0),
                    coalesce(public.sync_j(v_payload, 'category', 'category'), 'other'),
                    public.sync_j(v_payload, 'description', 'description'),
                    coalesce(public.sync_j(v_payload, 'sourceType', 'source_type'), 'bulk_import'),
                    public.sync_j(v_payload, 'sourceId', 'source_id'),
                    public.sync_j(v_payload, 'method', 'method'),
                    public.sync_j(v_payload, 'receiptNumber', 'receipt_number'),
                    public.sync_j(v_payload, 'paymentStatus', 'payment_status'),
                    public.sync_j(v_payload, 'reversesId', 'reverses_id'),
                    coalesce(public.sync_safe_uuid(coalesce(v_payload->>'actorId', v_payload->>'actor_id'))::text, m->>'actor_id'),
                    coalesce(public.sync_j(v_payload, 'actorName', 'actor_name'), 'System'),
                    nullif(btrim(coalesce(v_payload->>'at', '')), '')::timestamptz,
                    v_payload->'metadata'
                );
            when 'installment' then
                perform public.upsert_installment_from_import(
                    v_tenant,
                    coalesce(public.sync_j(v_payload, 'parentId', 'parent_id'), ''),
                    coalesce(public.sync_j(v_payload, 'id', 'installment_ref'), m->>'id'),
                    public.sync_j(v_payload, 'studentId', 'student_id'),
                    coalesce(public.sync_j(v_payload, 'category', 'category'), 'tuition'),
                    public.sync_j(v_payload, 'label', 'label'),
                    nullif(btrim(coalesce(v_payload->>'amountDue', v_payload->>'amount_due', '')), '')::numeric,
                    nullif(btrim(coalesce(v_payload->>'amountPaid', v_payload->>'amount_paid', '')), '')::numeric,
                    nullif(btrim(coalesce(v_payload->>'amountPending', v_payload->>'amount_pending', '')), '')::numeric,
                    nullif(btrim(coalesce(v_payload->>'dueDate', v_payload->>'due_date', '')), '')::date,
                    nullif(btrim(coalesce(v_payload->>'paidDate', v_payload->>'paid_date', '')), '')::date,
                    coalesce(public.sync_j(v_payload, 'status', 'status'), 'unpaid'),
                    public.sync_j(v_payload, 'academicCycle', 'academic_cycle'),
                    public.sync_j(v_payload, 'academicYear', 'academic_year')
                );
            when 'attendance' then
                perform public.upsert_attendance_from_import(
                    v_tenant,
                    public.sync_safe_uuid(coalesce(v_payload->>'studentId', v_payload->>'student_id')),
                    nullif(btrim(coalesce(v_payload->>'recordDate', v_payload->>'record_date', v_payload->>'date', '')), '')::date,
                    coalesce(public.sync_j(v_payload, 'status', 'status'), 'present'),
                    public.sync_safe_uuid(coalesce(v_payload->>'classId', v_payload->>'class_id')),
                    coalesce(public.sync_j(v_payload, 'session', 'session'), 'morning'),
                    public.sync_j(v_payload, 'arrivalTime', 'arrival_time'),
                    public.sync_j(v_payload, 'note', 'note'),
                    public.sync_safe_uuid(coalesce(v_payload->>'recordedBy', v_payload->>'recorded_by', m->>'actor_id'))
                );
            when 'grade' then
                perform public.upsert_assessment_from_import(
                    v_tenant,
                    public.sync_safe_uuid(coalesce(v_payload->>'studentId', v_payload->>'student_id')),
                    public.sync_safe_uuid(coalesce(v_payload->>'subjectId', v_payload->>'subject_id')),
                    coalesce((coalesce(v_payload->>'term', '1'))::integer, 1),
                    coalesce(public.sync_j(v_payload, 'academicYear', 'academic_year'), ''),
                    public.sync_safe_uuid(coalesce(v_payload->>'classId', v_payload->>'class_id')),
                    nullif(btrim(coalesce(v_payload->>'devoir1', '')), '')::numeric,
                    nullif(btrim(coalesce(v_payload->>'devoir2', '')), '')::numeric,
                    nullif(btrim(coalesce(v_payload->>'examen', '')), '')::numeric,
                    coalesce((coalesce(v_payload->>'coefficient', '1'))::numeric, 1),
                    public.sync_safe_uuid(m->>'actor_id')
                );
            when 'homework' then
                -- The table upsert (the canonical path — no dedicated import
                -- RPC exists for homework on either client).
                if public.sync_j(v_payload, 'id', 'id') is null
                    or public.sync_j(v_payload, 'classId', 'class_id') is null
                    or public.sync_j(v_payload, 'subjectId', 'subject_id') is null then
                    raise exception 'sync_apply_batch(homework): id, classId and subjectId are required';
                end if;
                insert into public.homework as v_homework_row (
                    id, tenant_id, class_id, subject_id, subject_name, teacher_id, teacher_name,
                    title, description, due_date, academic_year, pushed_at, created_at, attachments
                ) values (
                    public.sync_j(v_payload, 'id', 'id'),
                    v_tenant,
                    public.sync_j(v_payload, 'classId', 'class_id'),
                    public.sync_j(v_payload, 'subjectId', 'subject_id'),
                    public.sync_j(v_payload, 'subjectName', 'subject_name'),
                    public.sync_j(v_payload, 'teacherId', 'teacher_id'),
                    public.sync_j(v_payload, 'teacherName', 'teacher_name'),
                    coalesce(public.sync_j(v_payload, 'title', 'title'), 'Devoir'),
                    coalesce(v_payload->>'description', ''),
                    coalesce(public.sync_j(v_payload, 'dueDate', 'due_date'), ''),
                    public.sync_j(v_payload, 'academicYear', 'academic_year'),
                    nullif(btrim(coalesce(v_payload->>'pushedAt', '')), '')::timestamptz,
                    nullif(btrim(coalesce(v_payload->>'createdAt', v_payload->>'created_at', '')), '')::timestamptz,
                    v_payload->'attachments'
                )
                on conflict (id) do update set
                    subject_name = coalesce(excluded.subject_name, v_homework_row.subject_name),
                    teacher_id = coalesce(excluded.teacher_id, v_homework_row.teacher_id),
                    teacher_name = coalesce(excluded.teacher_name, v_homework_row.teacher_name),
                    title = excluded.title,
                    description = excluded.description,
                    due_date = excluded.due_date,
                    academic_year = coalesce(excluded.academic_year, v_homework_row.academic_year),
                    pushed_at = coalesce(excluded.pushed_at, v_homework_row.pushed_at),
                    attachments = coalesce(excluded.attachments, v_homework_row.attachments);
            else
                -- The SYNC-100 doctrine: NO silent no-ops — an unknown kind
                -- FAILS LOUD (and rolls the whole batch back).
                raise exception 'sync_apply_batch: no canonical push path for entity kind "%" — the batch is rolled back', v_entity;
        end case;

        v_ids := array_append(v_ids, m->>'id');
        v_results := v_results || jsonb_build_object('id', m->>'id', 'status', 'synced');
    end loop;

    -- The bulk mark: every applied entry's queue row → synced (atomic with
    -- the applies above — a mid-batch failure rolled BOTH back already).
    update public.sync_queue
       set status = 'synced',
           last_error = null,
           last_attempt_at = now(),
           pushed_at = now()
     where id = any (v_ids)
       and tenant_id = v_tenant;

    return v_results;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_ledger_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.entry_date IS NOT NULL AND (NEW.at IS NULL OR NEW.at <> NEW.entry_date) THEN
        NEW.at := NEW.entry_date;
    ELSIF NEW.at IS NOT NULL AND (NEW.entry_date IS NULL OR NEW.entry_date <> NEW.at) THEN
        NEW.entry_date := NEW.at;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.timetable_entries_guard_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_status text;
begin
    if TG_OP = 'DELETE' then
        select status into v_status from public.timetable_versions where id = old.version_id;
        if v_status in ('published','archived') then
            raise exception 'timetable_entries is immutable for published/archived version % (T-404). Duplicate the version to a draft to make changes.', old.version_id
                using errcode = 'P0001';
        end if;
        return old;
    end if;

    select status into v_status from public.timetable_versions where id = new.version_id;
    if v_status in ('published','archived') then
        raise exception 'timetable_entries is immutable for published/archived version % (T-404). Duplicate the version to a draft to make changes.', new.version_id
            using errcode = 'P0001';
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.unregister_fcm_token(p_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_row public.device_tokens%ROWTYPE;
    v_caller_profile uuid;
    v_is_service_role boolean;
BEGIN
    IF p_token IS NULL OR trim(p_token) = '' THEN
        RAISE EXCEPTION 'unregister_fcm_token: p_token is required';
    END IF;

    v_is_service_role := (auth.role() = 'service_role');

    SELECT * INTO v_row
      FROM public.device_tokens dt
     WHERE dt.token = p_token
     ORDER BY dt.is_active DESC, dt.last_seen_at DESC
     LIMIT 1;

    IF v_row.id IS NULL THEN
        RETURN NULL; -- nothing to retire (idempotent no-op)
    END IF;

    IF NOT v_is_service_role THEN
        SELECT up.id INTO v_caller_profile
          FROM public.user_profiles up
         WHERE up.auth_user_id = auth.uid()
         LIMIT 1;
        IF v_caller_profile IS NULL OR v_caller_profile <> v_row.user_id THEN
            RAISE EXCEPTION 'unregister_fcm_token: caller does not own the device token row %', v_row.id
              USING ERRCODE = '42501';
        END IF;
    END IF;

    UPDATE public.device_tokens
       SET is_active = false,
           last_seen_at = now()
     WHERE id = v_row.id
     RETURNING id INTO v_row.id;

    PERFORM public.write_audit_log(
        p_tenant_id   := v_row.tenant_id,
        p_action      := 'device_token.unregister',
        p_entity_type := 'device_token',
        p_entity_id   := v_row.id,
        p_actor_id    := v_row.user_id,
        p_after_json  := jsonb_build_object('is_active', false),
        p_note        := 'Retrait du jeton FCM (rotation / désactivation)'
    );

    RETURN v_row.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.upsert_attendance_from_import(p_tenant_id uuid, p_student_id uuid, p_record_date date, p_status text, p_class_id uuid DEFAULT NULL::uuid, p_session text DEFAULT 'morning'::text, p_arrival_time text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_recorded_by uuid DEFAULT NULL::uuid, p_recorded_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_id UUID;
    v_session TEXT := COALESCE(NULLIF(p_session, ''), 'morning');
    v_status  TEXT := COALESCE(NULLIF(p_status, ''), 'present');
BEGIN
    IF v_session NOT IN ('morning', 'afternoon', 'both') THEN
        RAISE EXCEPTION 'Invalid session: %', v_session;
    END IF;
    IF v_status NOT IN ('present', 'absent_excused', 'absent_unexcused', 'late') THEN
        RAISE EXCEPTION 'Invalid attendance status: %', v_status;
    END IF;

    INSERT INTO public.attendance_records (
        tenant_id, student_id, class_id, record_date, session, status,
        arrival_time, note, recorded_by, recorded_at, synced_at,
        created_at, updated_at
    ) VALUES (
        p_tenant_id, p_student_id, p_class_id, p_record_date, v_session, v_status,
        p_arrival_time, p_note, p_recorded_by, p_recorded_at, NOW(),
        NOW(), NOW()
    )
    ON CONFLICT (tenant_id, student_id, record_date, session) DO UPDATE SET
        status       = EXCLUDED.status,
        arrival_time = EXCLUDED.arrival_time,
        note         = EXCLUDED.note,
        class_id     = COALESCE(EXCLUDED.class_id, public.attendance_records.class_id),
        recorded_by  = EXCLUDED.recorded_by,
        recorded_at  = EXCLUDED.recorded_at,
        synced_at    = NOW(),
        updated_at   = NOW()
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_workflow_dag(p_definition jsonb, p_strict boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_nodes        jsonb;
    v_edges        jsonb;
    v_errors       text[] := '{}';
    v_warnings     text[] := '{}';
    v_node_ids     text[] := '{}';
    v_edge_ids     text[] := '{}';
    v_seen_pairs   text[] := '{}';
    v_subtype_map  jsonb := '{
        "trigger":   ["payment_overdue","student_enrolled","payment_recorded","schedule","absence_limit_exceeded","manual_run","grade_below_threshold","payment_cleared_or_bounced","document_expiration","calendar_cron_event","stock_level_critical"],
        "condition": ["debt_over_threshold","payment_method_match","student_status_match","time_window","route_switch","has_medical_justification"],
        "action":    ["send_email","apply_discount","create_invoice","push_notification","log_audit","send_whatsapp","restrict_account","dispatch_task","generate_document","account_adjustment"],
        "delay":     ["wait_duration"],
        "transform": ["database_query","extract_field"]
    }'::jsonb;
    v_node         jsonb;
    v_edge         jsonb;
    v_cfg          jsonb;
    v_id           text;
    v_type         text;
    v_subtype      text;
    v_source       text;
    v_target       text;
    v_pair         text;
    v_i            int;
    v_j            int;
    v_k            int;
    v_n            int;
    v_m            int;
    v_src_idx      int;
    v_tgt_idx      int;
    -- Kahn state: flat parallel arrays (deduped edge list) + 1-D in-degree.
    v_edge_src     int[] := '{}';
    v_edge_tgt     int[] := '{}';
    v_in_degree    int[];
    v_queue        int[];
    v_current      int;
    v_processed    int := 0;
    v_cycle_nodes  text[] := '{}';
    v_trigger_seen boolean := false;
    v_cond         jsonb;
    v_cond_text    jsonb;
    v_route        jsonb;
    v_duration     numeric;
begin
    -- ---------- structural: the definition object itself ----------
    if p_definition is null or jsonb_typeof(p_definition) <> 'object' then
        return jsonb_build_object('valid', false, 'errors',
            jsonb_build_array('definition must be a JSON object with nodes[] and edges[]'),
            'warnings', '[]'::jsonb, 'node_count', 0, 'edge_count', 0);
    end if;
    if not p_definition ? 'nodes' or jsonb_typeof(p_definition -> 'nodes') <> 'array' then
        return jsonb_build_object('valid', false, 'errors',
            jsonb_build_array('definition.nodes must be an array'),
            'warnings', '[]'::jsonb, 'node_count', 0, 'edge_count', 0);
    end if;
    if not p_definition ? 'edges' or jsonb_typeof(p_definition -> 'edges') <> 'array' then
        return jsonb_build_object('valid', false, 'errors',
            jsonb_build_array('definition.edges must be an array'),
            'warnings', '[]'::jsonb, 'node_count', 0, 'edge_count', 0);
    end if;

    v_nodes := p_definition -> 'nodes';
    v_edges := coalesce(p_definition -> 'edges', '[]'::jsonb);
    v_n := jsonb_array_length(v_nodes);
    v_m := jsonb_array_length(v_edges);

    if v_n = 0 then
        v_errors := array_append(v_errors, 'workflow has no nodes');
    end if;

    -- ---------- nodes: id, type, subtype ----------
    v_i := 0;
    for v_node in select jsonb_array_elements(v_nodes)
    loop
        v_i := v_i + 1;
        if jsonb_typeof(v_node) <> 'object' then
            v_errors := array_append(v_errors, format('node[%s] is not an object', v_i - 1));
            v_node_ids := array_append(v_node_ids, '§invalid' || v_i::text || '§');
            continue;
        end if;
        v_id := v_node ->> 'id';
        if v_id is null or v_id = '' then
            v_errors := array_append(v_errors, format('node[%s] has an empty/missing id', v_i - 1));
            v_id := '§invalid' || v_i::text || '§';
        elsif v_id = any(v_node_ids) then
            v_errors := array_append(v_errors, format('duplicate node id "%s"', v_id));
        end if;
        v_node_ids := array_append(v_node_ids, v_id);

        v_type := v_node ->> 'type';
        if v_type is null or not (v_type = any(array['trigger','condition','action','delay','transform'])) then
            v_errors := array_append(v_errors, format('node "%s" has invalid type "%s"', v_id, coalesce(v_type, '§null§')));
        else
            v_subtype := v_node ->> 'subtype';
            if v_subtype is null or v_subtype = '' then
                v_errors := array_append(v_errors, format('node "%s" (type %s) is missing its subtype', v_id, v_type));
            elsif not (v_subtype = any(array(select jsonb_array_elements_text(coalesce(v_subtype_map -> v_type, '[]'::jsonb))))) then
                v_errors := array_append(v_errors, format('node "%s": subtype "%s" is not registered for type %s', v_id, v_subtype, v_type));
            end if;
        end if;

        if v_type = 'trigger' then
            v_trigger_seen := true;
        end if;
    end loop;

    -- ---------- edges: id, refs, self, duplicate pairs ----------
    v_i := 0;
    for v_edge in select jsonb_array_elements(v_edges)
    loop
        v_i := v_i + 1;
        if jsonb_typeof(v_edge) <> 'object' then
            v_errors := array_append(v_errors, format('edge[%s] is not an object', v_i - 1));
            continue;
        end if;
        v_id := v_edge ->> 'id';
        if v_id is null or v_id = '' then
            v_warnings := array_append(v_warnings, format('edge[%s] has no id (tolerated — key is (source,target))', v_i - 1));
        elsif v_id = any(v_edge_ids) then
            v_errors := array_append(v_errors, format('duplicate edge id "%s"', v_id));
        end if;
        v_edge_ids := array_append(v_edge_ids, v_id);

        v_source := v_edge ->> 'source';
        v_target := v_edge ->> 'target';
        if v_source is null or v_source = '' or not (v_source = any(v_node_ids)) then
            v_errors := array_append(v_errors, format('edge "%s" references unknown source node "%s"', coalesce(v_id, format('edge[%s]', v_i - 1)), coalesce(v_source, '§null§')));
        end if;
        if v_target is null or v_target = '' or not (v_target = any(v_node_ids)) then
            v_errors := array_append(v_errors, format('edge "%s" references unknown target node "%s"', coalesce(v_id, format('edge[%s]', v_i - 1)), coalesce(v_target, '§null§')));
        end if;
        if v_source is not null and v_source = v_target then
            v_errors := array_append(v_errors, format('edge "%s" is a self-reference on node "%s"', coalesce(v_id, format('edge[%s]', v_i - 1)), v_source));
        end if;
        if v_source is not null and v_target is not null and v_source <> v_target
           and (v_source = any(v_node_ids)) and (v_target = any(v_node_ids)) then
            v_pair := v_source || '->' || v_target;
            if v_pair = any(v_seen_pairs) then
                v_errors := array_append(v_errors, format('duplicate edge between "%s" and "%s"', v_source, v_target));
            else
                -- Deduped edge list for the Kahn walk (first pair wins).
                v_edge_src := array_append(v_edge_src, array_position(v_node_ids, v_source));
                v_edge_tgt := array_append(v_edge_tgt, array_position(v_node_ids, v_target));
            end if;
            v_seen_pairs := array_append(v_seen_pairs, v_pair);
        end if;
    end loop;

    -- ---------- Kahn cycle detection (in-degree walk, flat edge arrays) ----------
    if v_n > 0 and coalesce(array_length(v_node_ids, 1), 0) = v_n then
        for v_i in 1..v_n loop
            v_in_degree[v_i] := 0;
        end loop;
        for v_k in 1..coalesce(array_length(v_edge_src, 1), 0) loop
            v_in_degree[v_edge_tgt[v_k]] := coalesce(v_in_degree[v_edge_tgt[v_k]], 0) + 1;
        end loop;

        for v_i in 1..v_n loop
            if coalesce(v_in_degree[v_i], 0) = 0 then
                v_queue := array_append(v_queue, v_i);
            end if;
        end loop;

        while coalesce(array_length(v_queue, 1), 0) > 0
        loop
            v_current := v_queue[1];
            v_queue := v_queue[2:coalesce(array_length(v_queue, 1), 1)];
            v_processed := v_processed + 1;
            for v_k in 1..coalesce(array_length(v_edge_src, 1), 0) loop
                if v_edge_src[v_k] = v_current then
                    v_j := v_edge_tgt[v_k];
                    v_in_degree[v_j] := v_in_degree[v_j] - 1;
                    if v_in_degree[v_j] = 0 then
                        v_queue := array_append(v_queue, v_j);
                    end if;
                end if;
            end loop;
        end loop;

        if v_processed < v_n then
            for v_i in 1..v_n loop
                if coalesce(v_in_degree[v_i], 0) > 0 then
                    v_cycle_nodes := array_append(v_cycle_nodes, v_node_ids[v_i]);
                end if;
            end loop;
            v_errors := array_append(v_errors,
                format('cycle detected — %s node(s) involved: %s (Kahn)',
                       coalesce(array_length(v_cycle_nodes, 1), 0), array_to_string(v_cycle_nodes, ', ')));
        end if;

        -- Trigger in-degree rule (a trigger fed by another node is malformed).
        -- Computed from the deduped edge list (the walk above MUTATES
        -- v_in_degree, so it cannot be reused here).
        for v_node in select jsonb_array_elements(v_nodes)
        loop
            if (v_node ->> 'type') = 'trigger' then
                v_src_idx := array_position(v_node_ids, v_node ->> 'id');
                if v_src_idx is not null then
                    v_tgt_idx := 0;
                    for v_k in 1..coalesce(array_length(v_edge_tgt, 1), 0) loop
                        if v_edge_tgt[v_k] = v_src_idx then
                            v_tgt_idx := v_tgt_idx + 1;
                        end if;
                    end loop;
                    if v_tgt_idx > 0 then
                        v_errors := array_append(v_errors,
                            format('trigger node "%s" has incoming edges — triggers must be roots', v_node ->> 'id'));
                    end if;
                end if;
            end if;
        end loop;
    end if;

    -- ---------- strict-mode rules (publish gate) ----------
    if p_strict then
        if not v_trigger_seen and v_n > 0 then
            v_errors := array_append(v_errors, 'workflow has no trigger node (required for publishing)');
        end if;

        for v_node in select jsonb_array_elements(v_nodes)
        loop
            v_id := v_node ->> 'id';
            v_subtype := v_node ->> 'subtype';
            v_type := v_node ->> 'type';
            v_cfg := coalesce(v_node -> 'config', '{}'::jsonb);

            if v_type = 'condition' and v_subtype in ('debt_over_threshold','payment_method_match','student_status_match','has_medical_justification') then
                v_cond := coalesce(v_cfg -> 'condition', v_cfg -> '_condition');
                if v_cond is null then
                    -- legacy scalar configs tolerated with a warning
                    if v_cfg ? 'threshold' or v_cfg ? 'method' or v_cfg ? 'status' then
                        v_warnings := array_append(v_warnings,
                            format('node "%s": legacy scalar condition config (no canonical condition tree)', v_id));
                    else
                        v_errors := array_append(v_errors,
                            format('node "%s": condition node has no condition configured', v_id));
                    end if;
                elsif jsonb_typeof(v_cond) = 'string' then
                    begin
                        v_cond_text := (v_cond #>> '{}')::jsonb;
                        if not public.workflow_condition_valid(v_cond_text) then
                            v_errors := array_append(v_errors, format('node "%s": malformed condition tree', v_id));
                        end if;
                    exception when others then
                        v_errors := array_append(v_errors, format('node "%s": condition is a string but not valid JSON', v_id));
                    end;
                elsif not public.workflow_condition_valid(v_cond) then
                    v_errors := array_append(v_errors, format('node "%s": malformed condition tree', v_id));
                end if;
            end if;

            if v_type = 'condition' and v_subtype = 'route_switch' then
                if not (v_cfg ? 'routes') or jsonb_typeof(v_cfg -> 'routes') <> 'array' then
                    v_errors := array_append(v_errors, format('node "%s": route_switch has no routes configured', v_id));
                else
                    for v_route in select jsonb_array_elements(v_cfg -> 'routes')
                    loop
                        if jsonb_typeof(v_route) <> 'object' or not (v_route ? 'condition') then
                            v_errors := array_append(v_errors, format('node "%s": a route is missing its condition', v_id));
                        elsif not public.workflow_condition_valid(v_route -> 'condition') then
                            v_errors := array_append(v_errors, format('node "%s": a route condition is malformed', v_id));
                        end if;
                    end loop;
                end if;
            end if;

            if v_type = 'delay' and v_subtype = 'wait_duration' then
                if v_cfg ? 'duration_ms' then
                    begin
                        v_duration := (v_cfg ->> 'duration_ms')::numeric;
                        if v_duration is null or v_duration <= 0 then
                            v_errors := array_append(v_errors, format('node "%s": wait_duration must be a positive duration_ms', v_id));
                        end if;
                    exception when others then
                        v_errors := array_append(v_errors, format('node "%s": duration_ms is not a number', v_id));
                    end;
                else
                    v_errors := array_append(v_errors, format('node "%s": wait_duration has no duration_ms', v_id));
                end if;
            end if;
        end loop;
    end if;

    return jsonb_build_object(
        'valid', (coalesce(array_length(v_errors, 1), 0) = 0),
        'errors', to_jsonb(v_errors),
        'warnings', to_jsonb(v_warnings),
        'node_count', v_n,
        'edge_count', v_m
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.workflow_condition_valid(p_node jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_kind       text;
    v_combinator text;
    v_child      jsonb;
begin
    if p_node is null or jsonb_typeof(p_node) <> 'object' then
        return false;
    end if;
    v_kind := p_node ->> 'kind';
    if v_kind = 'comparison' then
        return p_node ? 'field'
           and jsonb_typeof(p_node -> 'field') = 'string'
           and (p_node ->> 'field') <> ''
           and p_node ? 'op'
           and (p_node ->> 'op') in ('>', '<', '>=', '<=', '==', '!=');
    elsif v_kind = 'logic' then
        v_combinator := p_node ->> 'combinator';
        if v_combinator not in ('and', 'or', 'not') then
            return false;
        end if;
        if not p_node ? 'children' or jsonb_typeof(p_node -> 'children') <> 'array' then
            return false;
        end if;
        if v_combinator = 'not' and jsonb_array_length(p_node -> 'children') <> 1 then
            return false;
        end if;
        for v_child in select jsonb_array_elements(p_node -> 'children')
        loop
            if not public.workflow_condition_valid(v_child) then
                return false;
            end if;
        end loop;
        return true;
    end if;
    return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.workflows_publish_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    v_result jsonb;
    v_errors text[];
begin
    if new.status = 'published'
       and (old.status is distinct from 'published'
            or new.dag_definition is distinct from old.dag_definition) then
        v_result := public.validate_workflow_dag(new.dag_definition, true);
        if not (v_result ->> 'valid')::boolean then
            v_errors := array(select jsonb_array_elements_text(v_result -> 'errors'));
            raise exception 'workflow publish rejected: %',
                    array_to_string(v_errors, ' | ')
                using errcode = '23514';
        end if;
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.workflows_publish_gate_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    v_result jsonb;
    v_errors text[];
begin
    if new.status = 'published' then
        v_result := public.validate_workflow_dag(new.dag_definition, true);
        if not (v_result ->> 'valid')::boolean then
            v_errors := array(select jsonb_array_elements_text(v_result -> 'errors'));
            raise exception 'workflow publish rejected: %',
                    array_to_string(v_errors, ' | ')
                using errcode = '23514';
        end if;
        -- Direct-insert publish: the publish counter starts at 1.
        if coalesce(new.version, 0) < 1 then
            new.version := 1;
        end if;
    end if;
    return new;
end;
$function$
